quests[77343] = { id = 77343, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine tyränenreiche Wiedervereinigung", sourceObjective = "Lauscht dem Gespräch zwischen den Aspekten und Tyr.", progress = "Einen Augenblick, {name}. Ich will hören, was Tyr und die Aspekte sagen!", completion = "Ich kann kaum glauben, dass dieser Moment nun endlich gekommen ist, {name}. So viele Jahre in den Diensten von Tyrs Wache, in denen wir mitansehen mussten, wie die Wächter von Tyrs Grab einer nach dem anderen starben. Und jetzt sind sowohl er als auch seine Wache wiederbelebt!", sourceObjectiveStatus = "unverified-source-field" }
quests[77344] = { id = 77344, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeit zum Verdauen", description = "Tyr ist nach Jahrtausenden zu uns zurückgekehrt. Ich weiß ehrlich gesagt nicht einmal mehr, wie viele Jahrtausende es waren. Seine Welt hat sich verändert, sogar mehr, als wir uns überhaupt vorstellen können. Er wird viele Fragen haben, auf die er Antworten benötigt.\n\nIn der Zwischenzeit gibt es nichts, was die Mitglieder von Tyrs Wache lieber tun würden, als sich mit Tyr zu unterhalten. Tyrs Ruhestätte scheint mir der perfekte Ort zu sein, um ihm Zeit zu geben und seine Fragen zu beantworten - und ihn die Antworten verdauen zu lassen. Würdet Ihr ihn bitten, uns dort zu treffen?", sourceObjective = "Ladet Tyr ein, zu Tyrs Wache in Tyrs Ruhestätte zu stoßen.", progress = "Das sind wirklich interessante Zeiten, in denen wir leben, {name}...", completion = "Es tut so gut, direkt mit Tyr sprechen zu können. Es gibt so vieles, das wir ihm erzählen müssen, und ich weiß, dass wir alle Fragen an ihn haben.\n\nDanke, dass Ihr dies möglich gemacht habt, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[77345] = { id = 77345, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geschwindigkeitsrausch", description = "Manchmal werde Ihr weitere Strecken zurücklegen müssen.\n\nWenn Ihr keine Hindernisse überwinden müsst, ist 'Vorwärtsschub' die einfachste Möglichkeit, eine gute Geschwindigkeit beizubehalten, damit Ihr nicht abstürzt.\n\nFolgt wieder den Ringen zum Ziel und nutzt 'Vorwärtsschub', wenn Ihr aufgefordert werdet, Eure Geschwindigkeit zu halten.\n\nWenn Ihr feststeckt, nutzt die bronzene Taschenuhr, dann wird Celormu Euch zurücksetzen.", sourceObjective = "Fliegt durch die Ringe und landet im Zielgebiet.", completion = "Gut gemacht.\n\nDer Rest ist nur eine Frage der Übung.", sourceObjectiveStatus = "unverified-source-field" }
quests[77346] = { id = 77346, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schattenmondsprint", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[77347] = { id = 77347, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schattenmondsprint - Fortgeschritten", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[77348] = { id = 77348, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schattenmondsprint - Umgekehrt", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[77362] = { id = 77362, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forschung: Drakoniden der Verbotenen Insel" }
quests[77377] = { id = 77377, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf nach Tyrhold! Für Tyr!", description = "Wir haben uns erholt. Wir haben trainiert. Jetzt müssen wir uns Elisande stellen.\n\nBegleitet uns nach Tyrhold, wo Nozdormu, Chromie und Eternus bereits auf uns warten, um uns in die Nachtfestung zu schicken.\n\nWir werden uns die Scheibe zurückholen, und Tyr wird endlich wieder bei uns sein.", sourceObjective = "Sprecht mit Eternus in Tyrhold.", completion = "Seid Ihr sicher, dass Ihr bereit seid, zur Nachtfestung zu reisen?\n\nSeid Ihr sicher, dass Ihr wisst, womit Ihr es bei dieser \"Elisande\" zu tun bekommt?", sourceObjectiveStatus = "unverified-source-field" }
quests[77398] = { id = 77398, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Biokuppelbahn", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[77399] = { id = 77399, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Biokuppelbahn - Fortgeschritten", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[77400] = { id = 77400, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Biokuppelbahn - Umgekehrt", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[77408] = { id = 77408, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Weissagung regt sich", description = "Prophet Velen ist aus seiner Meditation erwacht und erbittet unverzüglich Eure Anwesenheit.\n\nEr wurde über eine Angelegenheit äußerster Wichtigkeit in Kenntnis gesetzt. Er würde in der Bewältigung dieser Angelegenheit sowohl Eure Stärke als auch Eure Weisheit schätzen.\n\nDer Prophet erwartet Euch an Bord der Vindikaar.\n\nNehmt diesen Kristall. Unsere Konstrukteure haben ihn auf die Teleportationsmatrix des Schiffes eingestimmt.", sourceObjective = "Verwendet den Teleportationskristall, um Prophet Velen an Bord der Vindikaar zu treffen.", completion = "Keine Angst, {name}. Zur Abwechslung ist die Lage diesmal nicht sehr ernst.\n\nTatsächlich bin ich... vorsichtig hoffnungsvoll. Und doch wird diese Hoffnung durch Sorge gemäßigt.", sourceObjectiveStatus = "unverified-source-field" }
quests[77409] = { id = 77409, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ungewissheit", description = "Während meiner Meditation zeigten sich mir zerstreute Visionen. Gelb und rot. Zerberstendes Glas. Ein plötzliches Gefühl der Wärme. Ich sehe meine eigene Hand vor mir, aber bin zu feige, sie zu ergreifen. Der teuflische Geruch von Argus.\n\nAls ich erwachte, erreichte mich eine Botschaft. Hatuun bittet um ein Treffen.\n\nNach dem Sieg über die Legion bot ich Hatuun und seinem Volk Hilfe dabei an, sich uns anzuschließen. Doch sie blieben auf Argus.\n\nHatuun hat sich seitdem nur noch selten bei uns gemeldet. Vielleicht hat er seine Meinung geändert.\n\nIch werde nach Krokuun reisen. Bitte, begleitet mich.", sourceObjective = "Sprecht mit Häuptling Hatuun in Krokuun.", completion = "Schauen wir mal, ob Velen uns auch wirklich die Hilfe bietet, die er uns einst zugesagt hat.\n\nDieses Mal gibt es nichts, das ihn abhalten könnte.", sourceObjectiveStatus = "unverified-source-field" }
quests[77410] = { id = 77410, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Offene Wunden", description = "Es waren meine Jäger, die Arzal'kal gefunden haben. Sie sagten, dass er ihnen dabei geholfen hat, mehrere Hinterhalte der Legion abzuwehren.\n\nWährend unserer ewigen Wacht auf Argus haben wir dergleichen noch nie gesehen. Er war schwächer als manche Dämonen, doch er war hartnäckig.\n\nEr sagte, er wolle mit Velen sprechen und wüsste, dass wir in Kontakt mit ihm stehen. Also habe ich seine Bitte gewürdigt.\n\nWenn Velen wirklich ist, wer er vorgibt zu sein, wird er selbst den unwürdigsten seiner Leute nicht zurückweisen.\n\nWir werden sehen. Ich erwarte nicht viel.", sourceObjective = "Sprecht mit Arzal'kal und hört ihn an.", progress = "Wenn Hatuun mich hergerufen hat, um zuzuhören, dann werde ich das auch.\n\nIch bin Hatuun diesen Respekt schuldig.", completion = "Was auch immer Arzal'kal Euch zeigen möchte, begleitet ihn bitte.\n\nIch muss hierbleiben und mit Hatuun unter vier Augen sprechen.", sourceObjectiveStatus = "unverified-source-field" }
quests[77411] = { id = 77411, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reue", description = "Seit dem Niedergang der Legion sind die Man'ari immer verzweifelter geworden. Einige greifen nach Macht. Andere isolieren sich. Wiederum andere haben Kulte gegründet und warten auf die Rückkehr von Sargeras. Sie glauben, dass er sie eines Tages wieder anführen wird.\n\nNalridun ist der Anführer eines solchen Kults. Er lebt zurückgezogen, aber es wird gemunkelt, dass er ein uraltes Relikt an sich gebracht hat, das Kil'jaeden bis zu seinem Tod aufbewahrt hat. Nalridun behauptet, dass er dadurch mit Sargeras Zwiesprache halten kann.\n\nIch glaube, ich kenne die Natur dieses Relikts. Wenn ich richtig liege, muss es zu Velen zurückgebracht werden.", sourceObjective = "Trefft Arzal'kal im Hain von Naroua, dann tötet Sprecher Nalridun und holt das uralte Draeneirelikt zurück.", progress = "Selbst wenn ich hier sterben sollte, dann wenigstens nicht aus einer Laune der Legion heraus.", completion = "Es ist geschafft.\n\nEin Übel wiedergutgemacht.\n\nMehr hatte ich mir gar nicht erhofft.", sourceObjectiveStatus = "unverified-source-field" }
quests[77412] = { id = 77412, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beweis und Beteuerung", description = "Mit Verstärkung ist nicht zu rechnen, doch das Relikt ist zu wichtig, um es zu riskieren. Ihr solltet damit sofort zu Prophet Velen zurückkehren.\n\nVor uns befindet sich ein Teleporter, den ich auf eins meiner Siegel abstimmen kann. Er wird Euch eine schnelle Beförderung ermöglichen.\n\nIch stoße später wieder zu Euch.", sourceObjective = "Bringt den glänzenden Stern zu Prophet Velen in Krokuun.", progress = "Ich spüre etwas sehr Mächtiges in Eurem Besitz.\n\nEs fühlt sich... vertraut an. Aber die Erinnerung ist so schwer zu fassen wie das Licht der Sonne.\n\nKonnte Arzal'kal Euch zu etwas führen?", completion = "Ist das...?", sourceObjectiveStatus = "unverified-source-field" }
quests[77414] = { id = 77414, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Traumsprungermittlung", description = "Der Smaragdgrüne Traum hat noch nie so in Azeroth hineingeblutet, {name}. Wir müssen genau verstehen, welche Auswirkungen dieses Phänomen hat, wenn wir uns auf alles Kommende vorbereiten wollen.\n\nVielleicht können wir das sogar zu unserem Vorteil nutzen.\n\nBrecht in das betroffene Gebiet auf und seht, was Ihr erfahren könnt. Bringt alles zurück, was interessant sein könnte, dann sehen wir, was wir tun können.", sourceObjective = "Schließt Aktivitäten im Traumsprung ab.", progress = "Wie geht es dem Traumsprung?", completion = "Mit diesen Informationen sollten wir in der Lage sein, den Traumsprung zu unserem Vorteil zu nutzen, {name}. Habt Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[77415] = { id = 77415, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die versteckte Hand", description = "Gerade in dem Moment, als er alleine war? Sie müssen ihn unbemerkt aus der Nähe beobachtet haben. Könnt Ihr die Höhle am anderen Ufer überprüfen?\n\nDiese Flunker sind berüchtigte Horter. Wenn die Drakoniden etwas zurückgelassen haben, könnte es immer noch dort sein.", sourceObjective = "Durchsucht Flunkerschätze nach Gegenständen von Neltharionagenten.", progress = "Habt Ihr die Höhle überprüft?", completion = "Was habt Ihr gefunden?", sourceObjectiveStatus = "unverified-source-field" }
quests[77417] = { id = 77417, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was eine Ewige ausmacht", description = "Eternus will uns eindeutig etwas mitteilen. Ich bin nicht sicher, wohin diese Unterhaltung führt.\n\nAber ich vertraue Chromie. Wenn sie glaubt, dass Eternus überzeugt werden kann, dann vertraue ich auf ihr Urteil.\n\nWenn Ihr bereit seid, werde ich mir anhören, was sie zu sagen hat.", sourceObjective = "Findet heraus, was Eternus zu sagen hat.", progress = "Es interessiert mich, was Eternus zu sagen hat.", completion = "Der Verlust ihrer Schwester Moraidormi ist die Wurzel allen Übels...", sourceObjectiveStatus = "unverified-source-field" }
quests[77423] = { id = 77423, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sprunghafte Träume", description = "Wandel naht, {name}. Wer auf den Smaragdgrünen Traum eingestimmt ist, kann es im Wind spüren.\n\nWir brauchen Eure Hilfe, um die Bedeutung dieses Wandels zu verstehen.\n\nWir wollen in dem betroffenen Bereich zusammenkommen und einen Plan ausarbeiten.", sourceObjective = "Trefft die Druiden, die den Traumsprung untersuchen.", completion = "Dieser wachsende \"Traumsprung\" betrifft uns alle. Wir haben viel zu untersuchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[77424] = { id = 77424, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forschung: Dracthyr der Verbotenen Insel" }
quests[77425] = { id = 77425, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schuppen voller Harpunen", description = "Die Djaradin haben Harpunen mit den Tuskarr gehandelt? Ich schätze, Fischharpunen sind nicht sehr effektiv gegen einen Drachen.\n\nWie groß, glaubt Ihr, war die Lieferung? Seht in der Nähe der Rüstmeisterin der Zaqali nach, ob sie irgendwelche alten Aufzeichnungen besitzt.", sourceObjective = "Sucht in der Nähe des Rüstmeisters der Zaqali nach Hinweisen auf Tuskarrhandel.", progress = "Ich weiß, dass die Djaradin normalerweise nicht für sorgfältige Aufzeichnungen bekannt sind. Aber da muss irgendetwas zu finden sein...", completion = "Ihr seid zurück! Mit guten Nachrichten, wie ich hoffe?", sourceObjectiveStatus = "unverified-source-field" }
quests[77426] = { id = 77426, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Übung macht den Meister: Rusziona", description = "Interessiert daran, eine schnellere Zeit zu erzielen?\n\n: Stürmt vorwärts.\n: Verhindert die Bewegung nach vorn.\n: Stellt sämtlichen Elan wieder her. Nur auf dem Boden verwendbar.", sourceObjective = "Helft Rusziona, durch die Ringe zu gleiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[77427] = { id = 77427, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Übung macht den Meister: Zhusadormu", description = "Interessiert daran, eine schnellere Zeit zu erzielen?\n\n: Verwandelt in ein ausgewachsenes Exemplar und erhöht die Geschwindigkeit.\n: Stellt 1 Elan wieder her, bis sämtlicher Elan wiederhergestellt ist.\n: Setzt Abklingzeiten zurück.", sourceObjective = "Helft Zhusadormu, durch die Ringe zu gleiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[77428] = { id = 77428, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Übung macht den Meister: Zalethgos", description = "Interessiert daran, eine schnellere Zeit zu erzielen?\n\n: Blinzelt vorwärts und macht einen Spurt.\n: Erhöht die Vorwärtsbeschleunigung.\n: Verbraucht 'Arkane Beschleunigung' und stellt Elan wieder her.", sourceObjective = "Helft Zalethgos, durch die Ringe zu gleiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[77429] = { id = 77429, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Übung macht den Meister: Posidriss", description = "Interessiert daran, eine schnellere Zeit zu erzielen?\n\n: Fliegt nach oben und stellt 1 Elan wieder her.\n: Erhöht die Dauer von 'Winde des Lebens' um 5 Sek.\n: Sprintet immer, wenn Ihr Elan wiederherstellt, vorwärts.", sourceObjective = "Helft Posidriss, durch die Ringe zu gleiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[77430] = { id = 77430, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Übung macht den Meister: Belastrasza", description = "Interessiert daran, eine schnellere Zeit zu erzielen?\n\n: Verbraucht im Laufe der Zeit allen Elan.\n: Stellt sämtlichen Elan her und erhaltet für jeden Elan einen Geschwindigkeitsschub.\n: Verbraucht 'Blutroter Flug' und setzt Abklingzeiten zurück.", sourceObjective = "Helft Belastrasza, durch die Ringe zu gleiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[77432] = { id = 77432, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pedgi der Durstige", description = "Pedgi benimmt sich dramatisch. Wieder einmal.\n\nIch weiß, es klingt kindisch, weil es das auch ist, aber er reagiert gut auf kleine Leckereien, wenn er in so einer Stimmung ist.\n\nKönntet Ihr ihm einen Kaffee aus dem Gasthaus unten holen?", sourceObjective = "Besorgt Pedgi ein Getränk vom Schankkellner des Gasthauses.", progress = "Pedgis Leckerli sollte dafür sorgen, dass er nicht mehr schmollt? Bei den Titanen, nicht zu glauben, dass ich so etwas mal sagen müsste...", completion = "Ich wusste ja, dass Musiker launisch sein können, aber das ist lächerlich. Wenigstens ist er wach.", sourceObjectiveStatus = "unverified-source-field" }
quests[77433] = { id = 77433, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausgrabung: Flussbett", description = "Es gibt ein Flussbett in der Nähe von Maruukai auf den Ebenen von Ohn'ahra, um das sich viele Geschichten über eine verlorene Karawane drehen!\n\nTrefft mich dort, so schnell Ihr könnt! Und zieht Eure besten alten, schlammerprobten Stiefel an!", sourceObjective = "Trefft Roska Felszahn an der Ausgrabungsstätte beim Flussbett auf den Ebenen von Ohn'ahra.", completion = "Mit diesem Fund werden wir die Welt der Zentauren erschüttern!", sourceObjectiveStatus = "unverified-source-field" }
quests[77434] = { id = 77434, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Technosehen: Observatorium", description = "Meine Wünschelruten deuten auf eine Gruppe von Ruinen der Drakoniden auf einem Hügel an der Küste des Erwachens.\n\nIch weiß nicht, was wir dort finden werden, aber es ist nie eine gute Idee, die Launen meiner Erfindungen zu hinterfragen. Sie liegen immer zu 97% richtig.\n\nImmer.", sourceObjective = "Trefft Zenata am Observatorium der Eintracht an der Küste des Erwachens.", completion = "Sollen wir einen Blick in die Vergangenheit dieser bröckelnden Steine werfen?", sourceObjectiveStatus = "unverified-source-field" }
quests[77436] = { id = 77436, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der brennende Grabhügel", description = "Fyrakks Truppen haben ihre Pläne bereits in Angriff genommen. Wir liegen einen Schritt zurück und müssen schnell handeln, wenn wir Amirdrassil erfolgreich schützen wollen.\n\nWährend Ihr auf dem Weg hierher wart, erhielten wir Nachricht von verdächtig aussehenden Gestalten, die in eine der Grabhöhlen in der Nähe eingedrungen sind. Tyrande ist bereits losgezogen, um nachzuforschen. Geht zu ihr und helft ihr.", sourceObjective = "Findet Tyrande in der Nähe des Grabhügels von Sor'theril.", completion = "Ihr kommt zur rechten Zeit, {class}. Ich benötige etwas Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[77437] = { id = 77437, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grenze des Äons", description = "Zeitwanderer Tempo und das Team haben endlich die Grenze des Äons aufgetaut!\n\nAlso... fast. Die Zeitwanderer haben die Dinge mehr oder weniger unter Kontrolle, aber die Grenze des Äons hat einige Probleme, bei denen die Bewohner der Stadt ein bisschen Hilfe gebrauchen könnten.\n\nSagt Bob, ich hätte euch geschickt!", sourceObjective = "Findet Schankkellner Bob an der Grenze des Äons.", completion = "Ich bin froh, dass Zera Euch geschickt hat! Es gibt hier ein paar Leute, die Hilfe gebrauchen könnten.", sourceObjectiveStatus = "unverified-source-field" }
quests[77483] = { id = 77483, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Technosehen: Drachenschädelinsel", description = "Ich habe meine Sensoren auf Relikte der Dracthyr eingestellt, und sie haben einen neuen Ort für unsere Untersuchungen vor der östlichen Küste der Verbotenen Insel markiert.\n\nDie hiesigen Drakoniden nennen ihn die Drachenschädelinsel. Ominös, oder? Ihr habt doch keine Angst, oder?", sourceObjective = "Trefft Zenata bei der Drachenschädelhöhle auf der Verbotenen Insel.", completion = "Meine Sensoren schlagen aus, wenn sie Höhleneingänge in der Nähe erkennen. Was wir suchen, befindet sich bestimmt darin.", sourceObjectiveStatus = "unverified-source-field" }
quests[77484] = { id = 77484, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Technosehen: Igiras Wacht", description = "Von allen Orten deuten meine Sensoren ausgerechnet auf einen interessanten Ort in der Zaralekhöhle hin.\n\nBringt auf diese Exkursion am besten eine Waffe mit. Meine ersten Untersuchungen deuten auf die Anwesenheit von Lava und Djaradin hin.", sourceObjective = "Trefft Zenata bei Igiras Wacht in der Zaralekhöhle.", completion = "Sie scheinen bereit zu sein, diese Höhle nacheinander zu verlassen...", sourceObjectiveStatus = "unverified-source-field" }
quests[77485] = { id = 77485, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Technosehen: Zurück zu Eadweard!", description = "Danke für Eure Hilfe!\n\nKehren wir zu Eadweard und den anderen in der Akademie zurück und gehen die Informationen durch, die wir gefunden haben.", sourceObjective = "Trefft Eadweard Dalyngrigge in der Akademie von Algeth'ar in Thaldraszus.", sourceObjectiveStatus = "unverified-source-field" }
quests[77486] = { id = 77486, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausgrabung: Blick von Neltharion", description = "Ein Niffenkollege von mir hat mir Untergrundinformationen über einen unterirdischen Turm gegeben. Er ist verlassen und liegt mitten in der Zaralekhöhle zwischen Loamm, den Djaradin und diesem garstigen Labor von Neltharion.\n\nPackt Eure Lieblingsschaufel und trefft mich dort!", sourceObjective = "Trefft Roska Felszahn beim Blick von Neltharion in der Zaralekhöhle.", completion = "Machen wir es wie die Niffen und graben wir diese verborgenen Geschichten aus.", sourceObjectiveStatus = "unverified-source-field" }
quests[77487] = { id = 77487, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausgrabung: Sitz des Schwingenfürsten", description = "Wir haben ein uraltes Fischerdorf in der Nähe der Verbotenen Insel entdeckt! Es ist ein kleines Eiland vor der nordwestlichen Küste mitsamt eigener, verfallener Brücke!\n\nIhr findet mich dort, wenn Ihr weiter im Dreck buddeln wollt.", sourceObjective = "Trefft Roska Felszahn am Sitz des Schwingenfürsten auf der Verbotenen Insel.", completion = "{name}! Ihr habt es geschafft!\n\nDie Seeluft macht einen richtig wach!", sourceObjectiveStatus = "unverified-source-field" }
quests[77488] = { id = 77488, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausgrabung: Zurück zu Eadweard!", description = "Gute Arbeit, {name}!\n\nWir haben viel Geschichte, von der wir Eadweard berichten können. Treffen wir uns in der Akademie!", sourceObjective = "Trefft Eadweard Dalyngrigge in der Akademie von Algeth'ar in Thaldraszus.", sourceObjectiveStatus = "unverified-source-field" }
quests[77570] = { id = 77570, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nuoberon, der wilde Traum eines Kindes" }
quests[77581] = { id = 77581, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Metzelt die Gnolle nieder!" }
quests[77589] = { id = 77589, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Totschlägertransit", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
