quests[77593] = { id = 77593, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Totschlägertransit - Umgekehrt", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[77644] = { id = 77644, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Scharlachrote Schlüssel", progress = "<Obwohl Staub und Rost sich an diesen Schlüsseln festgesetzt haben, sehen sie im Grunde nicht anders aus als der in Eurem Besitz.>", completion = "<Als Ihr den Schlüssel an seinen rechtmäßigen Platz zurücklegt, fällt es Euch schwer, der Neugier zu widerstehen, wozu er passen könnte. Da die anderen offensichtlich schon seit langer Zeit zu nichts mehr passen, wird ihn bestimmt niemand vermissen, falls Ihr ihn für die Zukunft ausborgen wollt.>" }
quests[77645] = { id = 77645, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Skettissause", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
