quests[77647] = { id = 77647, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Skettissause - Umgekehrt", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[77653] = { id = 77653, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Schlüsselgeschichte", description = "Hier für das Neueste vom Neuen? Nun, ich habe in der Tat Neuigkeiten für Euch.\n\nEin Waffenschmied war gerade noch hier und hat sich mit Tithris getroffen. Koref, wenn ich mich nicht täusche? Ich konnte zufällig mithören, wie sie über eine Art uralten Schlüssel gesprochen haben. Könnte interessant für Euch sein, wenn ich daran denke, wie vielen Artefakten Ihr nachgegangen seid.\n\nWaffenschmied Koref hat sich zurück auf den Weg zur Obsidianenklave gemacht. Ihr solltet Euch dort hinbegeben und sehen, was Ihr über diesen uralten Schlüssel in Erfahrung bringen könnt.", sourceObjective = "Sucht Waffenschmied Koref auf und befragt ihn zum Schlüssel.", completion = "Habt Ihr schon mal vom Titanenschlüssel gehört? Groß wie ein Zwerg und magieerfüllt. Die Titanen haben eine besondere Form verwendet, um diesen Schlüssel zu schmieden, doch die ist schon seit Ewigkeiten verschollen.\n\nGlücklicherweise hat Tithris ein Buch gefunden, von dem er glaubt, dass es zu eben jener Form führt! Das einzige Problem ist, dass der Text nicht gerade auf den Punkt kommt. Und ich bin nicht besonders gut darin, zwischen den Zeilen zu lesen.\n\nAber hey, mit all Eurer Erfahrung im Aufspüren von Artefakten könntet Ihr es ja mal versuchen! Ich erkläre mich nur zu gerne bereit, den Schlüssel zu schmieden, wenn Ihr die Form findet.", sourceObjectiveStatus = "unverified-source-field" }
quests[77662] = { id = 77662, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Hilferuf", sourceObjective = "Trefft Shandris und Lilian an den Reichtraumklippen.", completion = "{name}. Gut.\n\nWir haben unsere Beute in die Ecke gedrängt. Ich erkläre Euch unsere Mission.", sourceObjectiveStatus = "unverified-source-field" }
quests[77664] = { id = 77664, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein letzter Schritt", description = "Ohne Lilians Hilfe hätten wir es bei dieser Mission nie so weit gebracht.\n\nWir haben vielleicht nicht viel gemeinsam, aber Lilian ist... eine verlässliche Verbündete. Nachdem wir Seite an Seite im Traum kämpften, verbindet uns eine seltsame Geschwisterschaft, geschmiedet durch diese Mission.\n\nGemeinsam werden wir das beenden. Mit den Steinen in unserem Besitz ist es jetzt sicher, Raelas zu erledigen und seinem kleinen Kreuzzug ein Ende zu setzen.\n\nVorwärts.", sourceObjective = "Eliminiert Raelas Feuerwind.", completion = "Das war ein...\n\n<Shandris starrt in die Ferne und wirkt tief in Gedanken versunken. Dann schüttelt sie den Kopf, als ob sie ihn freibekommen wollte.>\n\nIch... Shae'lune will bestimmt einen Blick auf diese... Steine werfen wollen.", sourceObjectiveStatus = "unverified-source-field" }
quests[77665] = { id = 77665, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Euch gebunden", description = "Ich habe nicht lange mit Shandris zusammengearbeitet, aber... dieses Verhalten ist unüblich für sie.\n\nAber egal.\n\nWährend sie sich mit der... Logistik beschäftigt, sollten wir beide einen Weg suchen, diese Steine zu säubern.\n\nVielleicht weiß Shae'lune, was wir als Nächstes tun sollten.", sourceObjective = "Fragt Shae'lune, wie man die Steine reinigen kann.", completion = "Er wird nicht leicht, mit diesen Steinen fertigzuwerden, wenn Shandris irgendwohin verschwindet.", sourceObjectiveStatus = "unverified-source-field" }
quests[77673] = { id = 77673, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unter der Oberfläche", description = "Ich wusste von Anfang an, dass Shandris lieber allein arbeitet, aber sie könnte uns wenigstens wissen lassen, wohin sie geht.\n\nNicht gerade ein gutes Zeichen für unsere professionelle Zusammenarbeit.\n\nHüter Sillas spricht nicht mit mir...\n\nWir sollten uns im Lager umsehen. Vielleicht hat sie eine Notiz oder einen Hinweis hinterlassen... vielleicht in ihren Missionsaufzeichnungen?\n\nSeht nach und versucht, etwas aus Sillas herauszubekommen.\n\nIch warte hier, falls sie zurückkommt.", sourceObjective = "Findet Hinweise auf Shandris' Aufenthaltsort.", completion = "Ich kenne Shandris noch nicht lange, aber sie verhält sich merkwürdig.\n\nUnd nicht wie sie selbst.\n\nIch frage mich...", sourceObjectiveStatus = "unverified-source-field" }
quests[77674] = { id = 77674, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wunden der Vergangenheit", description = "Jetzt ergibt alles Sinn. Ich glaube, der vermisste Traumgeist hat sich mit ihr verbunden, wie Cyanthesa gesagt hat.\n\nEr lässt Shandris traumatische Momente aus ihrem Leben erneut erleben.\n\nEr ist nicht bösartig, aber der Geist und Shandris nähren sich an den Ängsten des jeweils anderen. Wir müssen sie ins Lager zurückbringen. Shae'lune kann ihr vielleicht helfen.\n\nSprecht mit ihr. Ich erscheine ihr zur Zeit wie der Feind. Aber vielleicht spricht sie mit Euch.", sourceObjective = "Sprecht mit Shandris und bringt sie zum Lager zurück.", completion = "Ich dachte, Shandris würde ihren Ärger an mir auslassen, weil ich eine Verlassene bin.\n\nIch dachte, jetzt, da wir die Aufgabe beendet haben, wäre sie mit mir fertig.\n\nEs wäre nicht das erste Mal.\n\nAber ich bin froh, dass ich mich geirrt habe. Ich habe... großen Respekt ihr und ihren Fähigkeiten gegenüber.\n\nWir müssen ihr helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[77675] = { id = 77675, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine bessere Zukunft, gemeinsam", description = "{name}, wir müssen mit Shae'lune zusammenarbeiten und ihr helfen, das Läuterungsritual mit Shandris durchzuführen.\n\nShae'lune sagt, sie hat es zuvor nur mit Gegenständen durchgeführt, nicht mit Personen. Es gibt... einige Risiken.\n\nAber ich habe Shandris kennengelernt. Sie würde dasselbe für mich tun.\n\nSprecht mit Shae'lune und befolgt ihre Anweisungen.", sourceObjective = "Helft Shae'lune, das Trennungsritual auf Shandris anzuwenden.", progress = "Ich werde Shandris helfen, so gut ich kann. Das ist das Mindeste, was ich für eine andere Soldatin tun kann.", completion = "Danke, {name}, dass Ihr uns mit Raelas und den Geistersteinen geholfen habt.\n\nIch werde mich um Shandris kümmern und sie bald zu Amirdrassil zurückbringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[77677] = { id = 77677, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Etwas Wasser...", description = "<Die Pflanze ist von Ruß und Flammen befreit, aber ihre Blätter hängen schlaff vor Durst herunter. Vielleicht weiß jemand vom Zentrallager Abhilfe zu schaffen.>", sourceObjective = "Pflegt die Pflanze, damit sie sich erholt.", progress = "<Die Blätter der Pflanze kräuseln sich bräunlich und an den Rändern sehen sie brüchig aus.>", completion = "<Die Pflanze scheint sich teilweise erholt zu haben. Ihre Blätter neigen sich zu Euch, als wollte sie sich bedanken.>", sourceObjectiveStatus = "unverified-source-field" }
quests[77679] = { id = 77679, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Soridormi zu Hilfe", description = "Habt Ihr gehört? Zeitrisse öffnen sich im Tyrholdreservoir! Das ist eine Katastrophe! Die Leute berichten von Portalen in andere Zeitwege, die sich wie zufällig öffnen. Nun dringen alle möglichen fantastischen Kreaturen nach Azeroth.\n\nZum Glück ist Soridormi dort. Ich hörte, sie versammelt alle für einen Widerstand. Wenn Ihr helfen könnt, wäre sie sicher nicht abgeneigt.\n\nSie sollte noch im Tyrholdreservoir stationiert sein. Tut es für Valdrakken. Tut es für Azeroth!", sourceObjective = "Sprecht mit Soridormi beim Tyrholdreservoir.", completion = "Wir haben es mit gefährlichen Anomalien zu tun, die man \"Zeitrisse\" nennt. Wir waren mit unseren Zeitreisen ein wenig zu unvorsichtig. Nun dringen Kreaturen aus alternativen Zeitwegen in unsere Welt ein, und wir müssen sie zurückdrängen.\n\nDie Situation läuft rasant aus dem Ruder. Wir können jede Hilfe brauchen, die wir kriegen können. Tut, was ich sage, wenn ich es sage, dann können wir verhindern, dass sich das Gewebe der Realität auflöst.\n\nIhr seht aus, als könntet Ihr diese Herausforderung bewältigen. Geht dort raus und kämpft!", sourceObjectiveStatus = "unverified-source-field" }
quests[77681] = { id = 77681, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufruf an alle Kontrahenten!", description = "Das Handwerkerkonsortium hat eine Abmachung mit den Rüstmeistern in der Zuflucht des Gladiators getroffen!\n\nZusätzlich zu der üblichen mächtigen Kampfausrüstung, die sie anbieten, können würdige Kämpfer nun Marken kaufen, die sie in Handwerksaufträgen oder bei eigenen Herstellungsverfahren einsetzen können, um die Ausrüstung zur Verwendung auf Schlachtfeldern und in Arenen zu zertifizieren!\n\nZeigt diesen Handzettel Calderax, um zwei kostenlose Trophäen der Eroberung zu erhalten, aufs Haus!\n\n- Rabul", sourceObjective = "Bringt das Flugblatt zu Calderax in der Zuflucht des Gladiators von Valdrakken.", completion = "Moment... Ist es das, wofür ich es halte? Machen wir schon WIEDER diese Aktion? Ihr habt keine Ahnung, wie viele Handzettel ich letztes Mal bekommen habe.\n\nNaja, hier sind Eure Trophäen, wie versprochen. Verwendet sie, wenn Ihr Ausrüstung herstellt oder Handwerksaufträge vergebt, dann wird die Macht der Ausrüstung mit dem vergleichbar sein, was ich anzubieten habe. Perfekt, wenn Ihr nach etwas hochgradig Spezifischem oder nach etwas mit besonderen Verzierungen sucht... und bereit seid, etwas zusätzliche Arbeit reinzustecken.\n\nFragen? Dann meldet Euch beim Handwerkermarkt.", sourceObjectiveStatus = "unverified-source-field" }
quests[77684] = { id = 77684, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teufelsgrubentumult", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[77685] = { id = 77685, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teufelsgrubentumult - Fortgeschritten", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[77686] = { id = 77686, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teufelsgrubentumult - Umgekehrt", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[77697] = { id = 77697, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die richtige Nahrung...", description = "<Die Pflanze ist jetzt ein vielversprechender Schössling und hat sich dank Eurer Zuwendung gut entwickelt.\n\nAls Ihr die Blätter der Pflanze genau betrachtet, seht Ihr, dass sie an der Außenseite mit Tau bedeckt sind. Vielleicht kann die Pflanze mit der richtigen Nahrung noch weiter gedeihen.>", sourceObjective = "Besorgt etwas Dünger für die Pflanze.", progress = "<Die Pflanze ist gewässert, wirkt aber stark unterernährt.>", completion = "<Der Boden um den Schössling leuchtet schwach auf.>", sourceObjectiveStatus = "unverified-source-field" }
quests[77698] = { id = 77698, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eimer mit Süßigkeiten", sourceObjective = "Süßigkeiteneimer wie diesen hier gibt es in jeder Gaststätte zu finden. Na los... greift zu!", sourceObjectiveStatus = "unverified-source-field" }
quests[77711] = { id = 77711, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Und ein Hauch Magie", description = "Der Eifer, den Ihr hier bewiesen habt, ist bemerkenswert, {name}. Ich hätte nie gedacht, dass jemand, der nicht einmal seinen eigenen Eimer finden kann, zu so etwas imstande ist.\n\nIch glaube, der Schössling hat es fast geschafft. Und zusammen können wir seine Entwicklung zum Abschluss bringen.\n\nNehmt dieses Totem und platziert es in der Nähe einiger der geschwächten, flammenverderbten Wurzelpfleger, die man im Singenden Moor findet. Dadurch müssten die instabilen magischen Energien aus ihren Körpern herausgelöst und in etwas umgewandelt werden, das wir gebrauchen können.", sourceObjective = "Besiegt die Wurzelpfleger, während sie unter dem Einfluss des Druidentotems stehen.", progress = "Ist das Totem aufgeladen?", completion = "Perfekt!\n\nGebt her, dann werde ich die gespeicherte Energie in den umliegenden Boden entlassen.", sourceObjectiveStatus = "unverified-source-field" }
