quests[77739] = { id = 77739, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Flammen ersticken", sourceObjective = "Helft Shandris und Lilian, die Geistersteine von den Dryaden der Schwestern der Flamme zurückzuholen.", progress = "Bringt mir alle vier Geistersteine. Wir müssen sie gut aufbewahren, damit sie nicht in die falschen Hände geraten.", completion = "Gut!\n\n<Shandris verstaut die Geistersteine in einem kleinen Lederbeutel.>\n\nNun lasst uns Raelas Wahnsinn beenden.", sourceObjectiveStatus = "unverified-source-field" }
