quests[77756] = { id = 77756, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flug der Drachen" }
quests[77757] = { id = 77757, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schrecken in der Zuflucht" }
quests[77760] = { id = 77760, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seltsamer Fund: Drachenhornflöte", description = "<Diese Flöte ist grob aus einem Drachenhorn geschnitzt. Risse an der Unterseite deuten darauf hin, dass der Drache schon lange tot war, als diese Flöte hergestellt wurde.\n\nDas Mundstück der Flöte sieht seltsam aus. Es ist fast, als ob sie überhaupt nicht mit dem Mund gespielt würde, sondern mit der Nase. Könnte diese Flöte von einem Niffen stammen?\n\nEadweard wird wissen, wie man diesen Fund erhalten kann und wie man herausfindet, von wem er stammt.>", sourceObjective = "Bringt die Drachenhornflöte zu Eadweard Dalyngrigge in der Akademie von Algeth'ar in Thaldraszus.", completion = "Aha! Ein interessanter Fund. Ich werde sofort Kontakt zu den relevanten Leuten aufnehmen, dann können wir den Fund dokumentieren und schnellstmöglich nach Hause bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[77761] = { id = 77761, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dokumentation eines Traums" }
quests[77762] = { id = 77762, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein bisschen Hoffnung ist immer gut", description = "Die Pflanze ist ausgewachsen und gedeiht. Diese kleine Ecke unseres Ökosystems ist wiederhergestellt, und ich habe etwas gesehen, das ich mir schon wünschte, seit ich erfuhr, was Euch umtreibt: Die Traumkrallen sind mit ihren Nachkommen zurückgekehrt!\n\nEine der dankbaren ausgewachsenen Traumkrallen hat Euch ihre Dienste angeboten, sofern Ihr das wünscht.", sourceObjective = "Sprecht mit Professor Esche.", completion = "Wenn Ihr die Traumkralle so behandelt, wie Ihr diese Pflanze behandelt habt, kann sie sich wirklich glücklich schätzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[77763] = { id = 77763, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seltsamer Fund: Durchnässtes Hauptbuch", description = "<Dieses ledergebundene Buch ist so aufgeweicht, dass es fast auseinanderfällt.\n\nDas meiste ist unleserlich, aber der verbleibende Text ist in einem uralten drakonischen Dialekt geschrieben. Es scheint sich um unzählige Listen von Alltagsgegenständen mit daneben verzeichneten Zahlen zu handeln. Vielleicht ein Haushaltsbuch?\n\nEadweard wird wissen, wie man diesen Fund erhalten kann und wie man herausfindet, von wem er stammt.>", sourceObjective = "Bringt das durchnässte Hauptbuch zu Eadweard Dalyngrigge in der Akademie von Algeth'ar in Thaldraszus.", completion = "Aha! Ein interessanter Fund. Ich werde sofort Kontakt zu den relevanten Leuten aufnehmen, dann können wir den Fund dokumentieren und schnellstmöglich nach Hause bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[77765] = { id = 77765, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dokumentation eines Traums" }
quests[77766] = { id = 77766, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seltsamer Fund: Gelochter Bakarzahn", description = "<Dieser Milchzahn stammt von einem jungen Bakar, aber der Knochen ist vergilbt, was darauf hindeutet, dass er Tausende von Jahren alt ist.\n\nJemand hat vorsichtig ein Loch in den Zahn gebohrt und einen Anhänger daraus gemacht. Bei genauerer Betrachtung könnt Ihr sogar die Überreste einer Wollkordel erkennen.\n\nEadweard wird wissen, wie man diesen Fund erhalten kann und wie man herausfindet, von wem er stammt.>", sourceObjective = "Bringt den gelochten Bakarzahn zu Eadweard Dalyngrigge in der Akademie von Algeth'ar in Thaldraszus.", completion = "Aha! Ein interessanter Fund. Ich werde sofort Kontakt zu den relevanten Leuten aufnehmen, dann können wir den Fund dokumentieren und schnellstmöglich nach Hause bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[77777] = { id = 77777, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rubinlebensschrein-Schleife – Sturmgreif", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[77779] = { id = 77779, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Geschichte von Sire Thomas", description = "Suzannah... Ich hätte nicht geglaubt, sie je wiederzufinden. Jetzt können wir endlich zu unseren Kindern zurückkehren und in Frieden ruhen. Und das alles dank Euch, {name}.\n\nHabt Ihr noch mein Buch? Meine Geschichte hat ihr Ende erreicht und ich würde es gerne selbst niederschreiben.\n\n<Thomas fährt mit dem Finger über eine leere Seite und spektrale Tinte hält seine Worte fest.>\n\nBringt es doch bitte der Waisenmatrone zurück und... entschuldigt Euch in meinem Namen für den Schrecken, den ich ihr eingejagt habe, ja?", sourceObjective = "Kehrt zur Waisenmatrone zurück.\n\nBereitgestellter Gegenstand:", completion = "Also ist es vorbei? Der kopflose Reiter ist einmal mehr besiegt und der gefallene Paladin ist frei und kann in Frieden ruhen.\n\nWas den Leuten in Lordaeron zugestoßen ist, ist furchtbar. Das Mindeste, was sie verdient haben, ist die ewige Ruhe. Die Geschichte von Sir Thomas ist erschütternd. Sie ist eine Warnung und erinnert uns daran, in welche Abgründe blinder Eifer uns führen kann. \n\nIch bin Euch dankbar, dass Ihr ihm geholfen habt, Frieden zu finden, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[77780] = { id = 77780, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeuge einer Blüte", description = "Amirdrassil ist über die Grenzen des Traums hinaus aufgeblüht.\n\nLasst uns zu den Dracheninseln reisen und sehen, wo dieser neue Weltenbaum Wurzeln geschlagen hat.", sourceObjective = "Sprecht mit Merithra am Uralten Zweig in den Ebenen von Ohn'ahra.", completion = "<Merithras Gesicht leuchtet auf.>\n\nChampion, wir gehören zu den allerersten, die Amirdrassil hier auf Azeroth sehen. Dies ist ein wahrhaft kostbarer Moment.", sourceObjectiveStatus = "unverified-source-field" }
quests[77781] = { id = 77781, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine andere Form von Begeisterung", description = "Ich habe bemerkt, dass die Festlichkeiten die Aufmerksamkeit einiger Spriggans aus dem Ardenwald auf sich gezogen haben. Sie sind merkwürdige Kreaturen mit... interessanten Vorlieben.\n\nIhre Streiche sind mehr als lästig gewesen. Bitte beseitigt sie, damit die Feier in Frieden weitergehen kann.", sourceObjective = "Deckt 6 Sprigganschelme in Bel'ameth auf.", progress = "Habt Ihr sie alle entdeckt? Ich habe bereits von einem zwielichtigen Gerücht gehört, von dem ich vermute, dass sie es erfunden haben.", completion = "Vielen Dank, {name}. Ich schätze ihre Lebhaftigkeit, aber sie stehen heute Abend nicht auf unserer Gästeliste.", sourceObjectiveStatus = "unverified-source-field" }
quests[77784] = { id = 77784, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tyrhold-Tournee – Sturmgreif", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[77785] = { id = 77785, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Moor-Durchflug – Sturmgreif", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[77786] = { id = 77786, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vakthrosaufstieg – Sturmgreif", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[77787] = { id = 77787, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sturmrisskrater-Rundflug – Sturmgreif", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[77788] = { id = 77788, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aschphodill-Forschungsnotizen", description = "<Ihr findet einige unterzeichnete Forschungsnotizen bei einem toten Druiden.\n\nDie Notizen beschreiben Experimente, die von den Druiden der Flamme durchgeführt wurden.\n\nIhr erfahrt, dass sie einen ungewöhnlichen Pollen hergestellt haben, der in der Lage ist, die Flora des Traums mit ihrer Flammenmagie zu erfüllen. Die nächste Stufe zielt mit demselben Pollen auf die Wildtiere ab.\n\nQ'onzu wäre sicherlich interessiert an einer Probe des Pollens und diesen Notizen.>", sourceObjective = "Sammelt eine Probe Glutpollen.", progress = "<Q'onzu blinzelt langsam, als er Euch anstarrt.>", completion = "Das... war vernichtend banal. Ruß und Asche, für immer unverwandelt?\n\n<Q'onzu schüttelt den gewaltigen Kopf.>\n\nNein. Das gefällt mir nicht.", sourceObjectiveStatus = "unverified-source-field" }
quests[77789] = { id = 77789, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durchtrennte Bande", description = "Nalridun hat eine kleine Armee an Kultisten rekrutiert. Sie glauben, dass er durch das Relikt für Sargeras spricht, und hängen ihm bei jedem einzelnen Wort an den Lippen. Genau wie wir damals an den Lippen unserer Anführer gehangen haben, als Sargeras nach Argus kam. Es war Trost. Hoffnung.\n\nUnd letzten Endes nichts als hohle Täuschung.\n\nDoch seine Anhänger glauben nicht, dass sie getäuscht werden. Sie haben in der Umgebung ihre eigenen Leitungen installiert, um die Macht des Relikts anzuzapfen. Um die Stimme selbst zu hören.\n\nSie werden versuchen, uns aufzuhalten. Wir werden uns einen Weg durch sie schlagen müssen.", sourceObjective = "Tötet 10 Kultisten der Man'ari und überladet 5 Leitungen der Sargerei.", progress = "Mögen ihre Einbildungen mit ihnen sterben.\n\nWir dürfen nicht riskieren, dass sie Nalriduns Ritualen mehr Macht verleihen.", completion = "Ich weiß, wie es ist, Angst zu haben. Aber sie hatten die Wahl. Und sie haben sich dafür entschieden, auf dem Pfad zu bleiben, den wir auf den schwelenden Überresten unzähliger Welten errichtet haben.\n\nAber wieso, wenn die erste Welt, die uns zum Opfer gefallen ist, unsere eigene Heimat war?", sourceObjectiveStatus = "unverified-source-field" }
quests[77791] = { id = 77791, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handhabung: Symbiotischer Leuchtsporengriff", description = "Ich kenne einen Handwerker, der helfen könnte, Fyr'alath zu schmieden. Erden vom Klan Shikaar ist enorm einfallsreich. Er hat viel mit allen möglichen Reagenzien der Dracheninseln experimentiert.\n\nJäger sind nur so gut, wie ihre Waffen. Erden ist dafür bekannt, ausgezeichnete Waffen aus exotischen Materialien herzustellen. Seine Expertise mit verschiedenster Flora und Fauna könnte sich als äußerst informativ herausstellen.", sourceObjective = "Sucht Erden auf den Ebenen von Ohn'ahra auf.", completion = "Verstehe.\n\nDiese Axt zu führen, könnte schmerzhaft sein. Lasst mich nachdenken.", sourceObjectiveStatus = "unverified-source-field" }
quests[77793] = { id = 77793, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kristallkreisel – Sturmgreif", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[77794] = { id = 77794, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wachtraumbelohnung" }
quests[77795] = { id = 77795, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erbeutete Artefakte", sourceObjective = "Wenn Ihr Vorräte habt, habe ich Waren. Alte Dinge. Manchmal heilige Dinge.", sourceObjectiveStatus = "unverified-source-field" }
quests[77802] = { id = 77802, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie soll ich Euch nennen?", description = "<Wächter/Wächterin>! Oder... <Lehrer/Lehrerin>! Elternteil?\n\nSagt Ihr mir, wie ich Euch nennen soll. Die anderen Dryaden werden mich fragen, wer mein Druide oder meine Druidin ist, da ich nun ganz allein im Garten arbeite.\n\nIch will ihnen sagen, dass ich gar keinen Druiden habe. Ich habe Euch!\n\nSagt mir, welchen Titel Ihr bevorzugt.", sourceObjective = "Sprecht mit Dionaessa im Wurzelbandrefugium, um Euren Titel auszuwählen.", completion = "Ein ausgezeichneter Titel! Ich werde ihn so oft benutzen, wie ich kann!\n\nDanke.", sourceObjectiveStatus = "unverified-source-field" }
quests[77813] = { id = 77813, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blitzschläge", description = "<Flatter legt eine Drehung hin und drückt Euch einen mit Sabber durchtränkten Zettel in die Hand.>\n\nAh, {name}. Ich hörte, dass Ihr Euch ein schönes neues Reittier zugelegt habt. Einen Greifen, der auf dem Sturm selbst segelt!\n\nIch würde zu gerne sehen, wie diese wundersame Kreatur fliegt. Ich werde im Himmelhochobservatorium auf Euch warten.", sourceObjective = "Trefft Lord Andestrasz im Himmelhochobservatorium.", completion = "Hallo noch mal, {name}. Dann kümmern wir uns mal um den Greifen!", sourceObjectiveStatus = "unverified-source-field" }
quests[77815] = { id = 77815, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Sturmrennentour", sourceObjective = "Fliegt jede der Sturmrennstrecken auf den Dracheninseln.", completion = "Gut gemacht! Dieser Sturmgreif ist ein wirklich beeindruckendes Geschöpf. Möget Ihr viele wundersame Abenteuer zusammen erleben!\n\nKlare Himmel und starke Winde, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[77818] = { id = 77818, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Grausame", description = "Primalisten, Djaradin und Druiden der Flamme arbeiten gemeinsam gegen uns.\n\nAber ich spüre, dass das nicht alles ist. Etwas Mächtiges versucht, durch dieses Portal zu kommen. Versuchen wir, sie so lange wie möglich auszusperren.", sourceObjective = "Helft Merithra, das Flammenportal zu schließen.", completion = "Ich bin froh, dass Ihr es geschafft habt. Uns bleibt keine andere Wahl, als uns zum Baum zurückzuziehen, bevor Fyrakks Streitkräfte eintreffen.\n\nUnd die Älteste Cassaphine... Ich fürchte, sie ist schon an diese Prophezeiung der Flamme verloren gegangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[77822] = { id = 77822, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine titanische Form", description = "<Die Titanenschlüsselform war an dem Ort, der in der Geschichte erwähnt wird. Waffenschmied Koref wird begeistert sein, die Form zu sehen!>", sourceObjective = "Bringt die Titanenschlüsselform zu Waffenschmied Koref in Valdrakken.", progress = "Beim Feuer meiner Schmiede... Habt Ihr es tatsächlich geschafft? Habt Ihr die Titanenschlüsselform gefunden?", completion = "Ich kann es nicht fassen, {name}! Wir haben nun die Form und müssen einfach nur den Schlüssel neu schmieden.\n\nIch muss Vorkehrungen treffen. Der Foliant, den Tithris mir gegeben hat, beschreibt einen komplexen Prozess. Magische Rituale, besondere Komponenten und dergleichen, Ihr versteht schon. Ich werde vermutlich Eure Hilfe brauchen, sobald ich alle meine Eisen geordnet habe.\n\nIch werde Euch benachrichtigen, sobald ich für den nächsten Schritt bereit bin.", sourceObjectiveStatus = "unverified-source-field" }
quests[77829] = { id = 77829, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Legende neuschmieden", description = "Da seid Ihr ja! Waffenschmied Koref hat gerade nach Euch gesucht. Hat mir eine Notiz dagelassen, in der er Euch darum bittet, ihn in der Obsidianenklave zu treffen.\n\nKlingt, als würdet Ihr ihm helfen, einen uralten Titanenschlüssel neu zu schmieden? Lasst mich wissen, wie es läuft! Das klingt nach einer Schlagzeile, wenn Ihr mich fragt.", sourceObjective = "Sucht Waffenschmied Koref in der Obsidianenklave auf.", completion = "Wir benötigen seltene Materialien für den Schlüssel. Einen besonderen Goldstaub und Flux. Ihr solltet beides an der Küste des Erwachens finden können.\n\nTrefft mich an der Schmiede des Erdwächters in der Obsidianzitadelle, sobald Ihr die Materialien beisammenhabt. Dort werde ich den Titanenschlüssel schmieden. Und wenn mein Amboss so will, mich in die Ränge legendärer Schmiede einreihen.\n\nHier, nehmt diese Notiz, darin findet Ihr alle Details. Wir stehen so kurz davor, {class}!", sourceObjectiveStatus = "unverified-source-field" }
quests[77831] = { id = 77831, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Schlüssel, neu zu schmieden", description = "Ihr habt die letzten Materialien! Perfekt.\n\nIch habe die Schmiede und die Form vorbereitet. Ihr müsst nur noch die Zutaten hinzufügen, wenn ich es sage.\n\nOh, und stellt Euch darauf ein, die Fackel von Pyrreth zu verwenden. Das Relikt scheint für den Schmiedeprozess ungemein wichtig zu sein. Ich sage Bescheid, wenn es so weit ist!", sourceObjective = "Helft Waffenschmied Koref, den Titanenschlüssel neu zu schmieden.", progress = "Der Titanenschlüssel. Ach du liebe Schmiede... Lasst mich mal sehen.", completion = "Das ist erstaunlich! Und er ist bereits kalt genug zum Anfassen? Welch unglaubliche Magie.\n\nHmm. Auf dem Schaft steht etwas geschrieben. Das meiste davon sagt mir nichts, aber das hier ist Tyrs Symbol. Ich zeichne den Rest der Nachricht kurz ab und schaue, was sich dazu herausfinden lässt.\n\nIch würde mal sagen, dass der Schlüssel bei Euch am sichersten ist. Aber was ist schon ein Schlüssel ohne das zugehörige Schloss? Und wenn jemand ein Titanenschloss finden kann, das geöffnet werden muss, dann ganz sicher Ihr.", sourceObjectiveStatus = "unverified-source-field" }
quests[77832] = { id = 77832, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schatten über Schatten", description = "Ich muss ihn retten.", sourceObjective = "Besiegt die Schatten.", sourceObjectiveStatus = "unverified-source-field" }
quests[77833] = { id = 77833, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handhabung: Konzentriertes weises Pergament", description = "Ich kenne eine Weise, die helfen kann, Fyr'alath zu härten. Shalasar Glimmerstaub ist eine Expertin des Intellektuellen und grübelt häufig über Theorien, wie man volatile Magie kontrollieren kann. Nur wenige verstehen weise Materialien so sehr wie sie.\n\nBittet sie um Hilfe im Umgang mit Schattenflamme. Ich vermute, ihre Lösung könnte eine Prise chromatischen Staubes beinhalten!", sourceObjective = "Sucht Shalasar Glimmerstaub auf den Ebenen von Ohn'ahra auf.", completion = "Ah, ja! Danke, dass Ihr hergekommen seid.\n\nDie anderen haben mich davor gewarnt, mich von der Akademie zu isolieren, aber ich wusste, dass es sich eines Tages auszahlen würde, an diesem entlegenen Örtchen in der Natur zu leben.", sourceObjectiveStatus = "unverified-source-field" }
quests[77835] = { id = 77835, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handhabung: Rune der Schattenbindung", description = "Lydiara Flüsterfeder ist eine Wissenschaftlerin, die die Unnachgiebigkeit der Regeln, die unsere Welt bestimmen, respektiert. Und doch versteht sie es, gerade diese zu verbiegen.\n\nWenn es jemanden gibt, der helfen kann, die Macht von Fyr'alath zu binden, dann sie.", sourceObjective = "Sucht Lydiara Flüsterfeder im Azurblauen Gebirge auf.", completion = "Ihr wollt Schattenflamme binden? Wie gefährlich! Wie waghalsig! Machen wir es.\n\nIch habe die Flora des Smaragdgrünen Traums studiert. Das Studium der exotischen und traumhaften Pflanzen dieses Reiches kann einen ziemlich ablenken, aber ich habe eine bestimmte gesehen, die uns bei der Suche nach Antworten helfen könnte.", sourceObjectiveStatus = "unverified-source-field" }
quests[77838] = { id = 77838, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausgefranstes Traumlaub", description = "Die Eigenschaften des Traumlaubs sind Euch fremd.\n\nWenn Ihr während der Superblüte Ereignisse abschließt, erhaltet Ihr das notwendige Wissen, um Verbündeten zu helfen.", sourceObjective = "Schließt während der Superblüte Ereignisse ab.", completion = "Schattentraumlaub ist immer noch rätselhaft, aber hoffentlich kann Euer Verbündeter dieses Wissen noch gebrauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[77839] = { id = 77839, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Strecken des Pokals der Östlichen Königreiche", description = "Es ist an der Zeit, Euren Mut wieder auf die Probe zu stellen.\n\nMeine Bronzekollegen sind in die Östlichen Königreiche gereist, um weitere Rennherausforderungen bereitzustellen. Viele Rennstrecken erwarten Euch auf dem ganzen Kontinent.\n\nSeid Ihr bereit?", sourceObjective = "Fliegt durch die Einführungsstrecken des Pokals der Östlichen Königreiche.", completion = "Ihr gebt den anderen Himmelsreitern den Weg vor! Wenn der Östliche-Königreiche-Pokal weitergeht, könnt Ihr dort weitere Rennen finden und Euren Schneid unter Beweis stellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[77840] = { id = 77840, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Pokal der Östlichen Königreiche beginnt", description = "<Himmelsreiter/Himmelsreiterin>! Ihr habt Lord Andestrasz gerade verpasst. Er ist auf der Suche nach fähigen Himmelsreitern wie Euch, die sich in den neuen Rennen messen!", sourceObjective = "Sucht Lord Andestrasz in Valdrakken auf.", completion = "Danke für Euren Besuch, Drachenreiter!", sourceObjectiveStatus = "unverified-source-field" }
quests[77841] = { id = 77841, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ysera-Einladungsturnier", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[77842] = { id = 77842, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ysera-Einladungsturnier - Fortgeschritten", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[77843] = { id = 77843, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ysera-Einladungsturnier - Umgekehrt", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[77844] = { id = 77844, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ysera-Einladungsturnier - Herausforderung", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[77845] = { id = 77845, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ysera-Einladungsturnier - Umgekehrte Herausforderung", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[77865] = { id = 77865, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein angemessenes Begräbnis", sourceObjective = "Heute bringt Ihr ein Grabesbanner der Maruuk zurück. Um ehrlich zu sein, hatte ich fast Angst, dass es jemand gestohlen haben könnte. Schon wieder! Aber nachdem ich das gesamte Gasthaus durchsucht hatte, sah ich noch einmal in meinem Spind nach, wo es sicher und wohlbehütet aufbewahrt war!\n\nDie jüngsten Ereignisse machen mir wohl langsam zu schaffen...\n\nBitte sprecht mit Sansok Khan in Maruukai und bringt das Banner dahin zurück, wo es hingehört.", sourceObjectiveStatus = "unverified-source-field" }
quests[77867] = { id = 77867, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Moruud" }
quests[77869] = { id = 77869, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zu den Echoinseln", description = "{name}, auf'n Echoinseln gibt's Ärger.\n\nRokhan bittet um Eure Hilfe.", sourceObjective = "Trefft Euch mit Rokhan auf den Echoinseln.", completion = "Gut, dass Ihr hier seid, {name}. Es braut sich was zusamm'.", sourceObjectiveStatus = "unverified-source-field" }
quests[77871] = { id = 77871, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die alt'n Loa", description = "Bwonsamdi kommt nich' ohne gut'n Grund persönlich vorbei. Hört, was er zu sag'n hat.\n\nDann denk'n wir. Und dann mach'n wir uns ans Werk.", sourceObjective = "Hört Euch Bwonsamdis Nachricht für die Dunkelspeertrolle an und findet eine Lösung.", progress = "Was Bwonsamdi sagt, klingt echt ernst. Die Anbetung von Mueh'zala ist 'ne blutige Sache.", completion = "Die Dunkelspeere ham immer mehrere Loa verehrt, aber Mueh'zala? Das krieg'n wir besser hin.\n\nUnser Weg ist offensichtlich.", sourceObjectiveStatus = "unverified-source-field" }
quests[77874] = { id = 77874, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Loa der Vergangenheit", description = "Wir müss'n die alt'n Loa find'n und zurückruf'n. Es muss 'nen Weg geb'n, herauszufind'n, wo sie hin sind.\n\nWenn wir die alt'n Loa find'n, könn' wir 'ne Prüfung der Loa veranstalt'n, um wieder an ihre Macht anzuknüpf'n.\n\nBwonsamdi meinte, dass sie immer noch da drauß'n sind. Ich glaub, er will uns 'nen Hinweis geb'n...", sourceObjective = "Findet einen Führer zu einem der verlorenen Loa, indem Ihr ein angemessenes Bildnis herstellt, und folgt ihm dann.", completion = "Ich spür, dass uns was beobachtet. Beurteilt. Der Loa is' schlau, aber wir auch.\n\nGeh'n wir weiter.", sourceObjectiveStatus = "unverified-source-field" }
quests[77877] = { id = 77877, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eins mit dem Loa", description = "Die Teile von Lukou sind überall verstreut.\n\nAber ihr Herz ist tief in dem Ogerhügel.\n\nDie Schatten können uns hinbringen. Leise. Schnell. Sprecht mit mir, wenn Ihr bereit seid.", sourceObjective = "Sprecht mit Kevo, um in den Ogerhügel der Mosh'Ogg gebracht zu werden.", completion = "Das war... echt heftig. Mein Magen is' immer noch verdreht!\n\nAber jetzt müss'n wir was erledigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[77878] = { id = 77878, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesandter des Winters" }
quests[77879] = { id = 77879, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Pirsch auf den Pirscher", description = "Wenn dieser Loa hier jagt, dann hat er uns vielleicht schon geseh'n. Da wir uns nich' sicher sein könn', sollt'n wir uns aufteil'n.\n\nIch werd ihn jag'n, während Ihr seine Aufmerksamkeit auf Euch zieht. Jani sagt, dass der Loa die Opfergab'n nimmt, die für Hakkar gedacht war'n, den Loa des Blutes.\n\nWir wiss'n aber nich', WIESO. Sammelt ein paar Opfergab'n und seht, ob er sie will. Wenn er was anderes möchte... dann werd'n wir das früh genug erfahr'n.", sourceObjective = "Sammelt 6 Opfergaben für Hakkar, um den Loa anzulocken.", progress = "<Kevo ya Siti prüft Eure Opfergaben.>", completion = "<Kevo ya Siti akzeptiert die Opfergaben stillschweigend.>\n\nIch will diese Opfergaben nicht für mich selbst. Hakkars Rückkehr zu verzögern, ist für uns alle von Vorteil.\n\nEs wird mehr brauchen, als sich nur zu erinnern. Eure Jagd hat gerade erst begonnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[77880] = { id = 77880, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nach Lukou schauen", description = "Das is' der letzte Ort, an dem Kevo ya Siti Lukou gespürt hat.\n\nWir müss'n rumfrag'n und rausfind'n, wer vielleicht weiß, wo sie hin is'.", sourceObjective = "Fragt nach Lukou und folgt der Spur, um sie zu finden.", progress = "Mit genug Informationen könn' wir Lukou aufspür'n.", completion = "Es wird Zeit, Lukou zu find'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[77881] = { id = 77881, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es gibt noch jemanden", description = "Wenn Mueh'zala beteiligt ist... werde ich helfen. Doch für eine Loaprüfung, mit der Mueh'zala vertrieben werden soll, brauchen wir noch jemanden.\n\nUnsere Loaschwester ist ebenfalls verloren. Wir waren ein Team, sie und ich, bis eine Unstimmigkeit uns auseinandergetrieben hat. Lukou ist der Loa der Regeneration. Sie ist der perfekte Loa, um als Gegengewicht für den Tod zu dienen.\n\nIch schulde ihr eine Entschuldigung. Ihr seid hier und es wird Zeit.\n\nIch habe ihre Präsenz zuletzt in der Nähe der kleinen Siedlung Bambala gespürt. Ich treffe Euch dort.", sourceObjective = "Begebt Euch nach Bambala und sucht Lukou.", completion = "Dieser Ort ist anders als in meiner Erinnerung.\n\nUnd ich kann unsere Schwester nicht spüren. Ich muss näher an sie herankommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[77882] = { id = 77882, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gestohlen, aber nicht vergessen", description = "Von dies'm Altar fehl'n viele Stücke. Wir müss'n ihn reparier'n, damit Lukou nicht verärgert wird, wenn sie zurückkehrt. Lukou muss seh'n, dass wir auf ihrer Seite sind.", sourceObjective = "Sammelt 8 Altarfragmente in der Nähe des Ogerhügels der Mosh'Ogg.", progress = "Wir brauch'n alle Teile, die Ihr find'n könnt.", completion = "Habt Ihr sie alle?", sourceObjectiveStatus = "unverified-source-field" }
quests[77885] = { id = 77885, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Traumwächter" }
quests[77886] = { id = 77886, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handhabung: Schattentraumlaub", description = "Wenn Fyr'alaths Macht bis an ihre Grenzen ausgereizt wird, werdet Ihr einen Griff brauchen, der sich selbst herunterkühlen kann. Ein wenig so, wie Ihr standhaft bleiben müsst, wenn ein wildes Tier auf Euch zustürmt: Wenn der Kampf hitzig wird, müsst Ihr konzentriert bleiben.\n\nEinige Lederarten der Dracheninseln besitzen diese kühlenden Eigenschaften, aber ich weiß etwas Besseres. Laub, das regelmäßig Schattenflamme ausgesetzt ist, wäre die perfekte Wahl, um die Komponenten zu verbinden. Sammeln wir, was Ihr braucht.", sourceObjective = "Sammelt Schattentraumlaub, indem Ihr in der Superblüte Ziele abschließt.", progress = "Habt Ihr gefunden, was wir brauchen?", completion = "Ausgezeichnet.\n\nWenn man lange genug nach etwas sucht, dann findet man es auch. Ich bin froh, dass wir genau das gefunden haben, was Ihr braucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[77889] = { id = 77889, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein feuriger Vorschlag", description = "Ah, hallo!\n\nIch habe vor Kurzem mit einigen Inschriftenkundigen gearbeitet. Wir haben eine neue Art Tinte hergestellt. Sie ist wie Feuertinte, nur noch feuriger!\n\nWir brauchen feurige Essenz von Feuerelementaren und im Moment greifen Feuerelementare den Traum an. Ich glaube, das nennt man \"Glück im Unglück\".\n\nBringt ihre Essenz bitte meinem Kollegen in Amirdrassil.", sourceObjective = "Sammelt 10 Exemplare feurige Essenz von Feuerelementaren im Smaragdgrünen Traum.", progress = "Den seltsamsten Quellen kann neues Wissen entspringen!", completion = "Ah, wunderbar. Ich werde die weiterleiten.\n\nDanke, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[77891] = { id = 77891, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Traum reparieren", description = "Ingenieurskunst ist eine exakte Wissenschaft! Wenn etwas explodiert, dann haben Ingenieure es so geplant.\n\nTräume sind nicht exakt, besonders nicht smaragdgrüne! Eines Tages wird jemand von einem Ingenieur verlangen, den Traum zu reparieren, und dann wissen wir nicht, wie. Wir brauchen viel mehr Informationen, um zu verstehen, womit wir es hier zu tun haben!\n\nGeht in den Traum und platziert Forschungsleuchtfeuer an den von mir bestimmten Orten. Sie werden die Informationen sammeln, die wir für zukünftige Reparaturen brauchen. Nutzt dieses praktische Teleportationsgerät, wenn Ihr die Orte schnell finden wollt.", sourceObjective = "Aktiviert 8 Forschungsleuchtfeuer.", completion = "So viele nützliche Daten über den Traum. Das wird die Ingenieure jahrelang beschäftigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[77892] = { id = 77892, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wertvolle Perlen", description = "Als Amirdrassils Wurzeln sich in das Wasser ausbreiteten, sind viele seltene Kreaturen aus den Tiefen des Ozeans emporgestiegen und gedeihen nun in den Träumen.\n\nEine solche seltene Kreatur ist die Sandschimmermuschel, die magische Perlen beinhalten kann!\n\nVersucht, diese Muscheln zu finden, und sammelt die Perlen in ihrem Inneren.", sourceObjective = "Sammelt 10 Sandschimmerperlen.", progress = "Habt Ihr ein paar Perlen gefunden?", completion = "Faszinierend, {name}, in der Macht dieser Perlen schlummert großes Potenzial.", sourceObjectiveStatus = "unverified-source-field" }
quests[77894] = { id = 77894, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Herz von Lukou", description = "Ich hatte gehofft, das wir mehr Stücke als die hier find'n, aber wir nehmen, was wir krieg'n, nich' wahr?\n\nRuft Lukou zum Altar. Hoffentlich antwortet sie.", sourceObjective = "Beschwört Lukou am Altar und sprecht mit ihr.", progress = "Wir sind fast da!", completion = "Danke für die Hilfe, {name}. Ich bin nich' schlimm verletzt word'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[77896] = { id = 77896, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine schläfrige Suche", description = "Während unseres Kampfs gegen Fyrakks Truppen ist eine Gruppe Druiden auf die Suche nach einem sicheren Rastplatz gegangen. Aber jetzt nähern sich Fyrakks Truppen ihrer Position...\n\nIch muss einen neuen Angriff vorbereiten. Ich kann meine Zeit leider nicht so aufteilen, wie ich möchte.\n\nIch habe sie zuletzt auf dem Weg nach Süden zu einer Höhle an der Küste gesehen. Stellt bitte sicher, dass es ihnen gut geht.", sourceObjective = "Seht nach den schlafenden Druiden.", completion = "Haben Fyrakks Truppen uns angegriffen?\n\nWie Ihr sehen könnt, gibt es hier kein derartiges Problem.\n\nAber ich habe ein viel größeres Problem zu lösen.", sourceObjectiveStatus = "unverified-source-field" }
quests[77897] = { id = 77897, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein besonderes Buch", sourceObjective = "Ah, da ist ja mein bester Ermittler.\n\nIch habe mit einer Kontaktperson bei den Kirin Tor gesprochen, die mir noch einen Gefallen schuldig ist. Sie gab mir einen Hinweis auf ein Buch in Karazhan, das uns helfen könnte, den Text auf den Tafeln zu entziffern, die Ihr geborgen habt. Ihr wisst doch, die vom Azurblauen Gebirge und aus den Wandernden Sanden?\n\nAber wir wissen ja beide, dass Ihr Experte darin seid, etwas aufzutreiben und zu sichern. Das ist die Notiz, die meine Kontaktperson hinterließ. Das sollte Euch dabei helfen, das Buch zu finden!", sourceObjectiveStatus = "unverified-source-field" }
quests[77898] = { id = 77898, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ehre und Tribut", description = "Es wird Zeit, nach Hause zurückzukehr'n. Lasst uns die Loa auf den Echoinseln willkommen heiß'n. Ihr positiver Einfluss sollte kurz'n Prozess mit Mueh'zalas Präsenz mach'n.\n\nGeht vor, ich bin direkt hinter Euch.", sourceObjective = "Errichtet die Altäre der Loa bei der Dunkelspeerfeste.", completion = "Alle Opfergaben sin' platziert. Mach'n wir den nächsten Schritt.", sourceObjectiveStatus = "unverified-source-field" }
quests[77899] = { id = 77899, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Rush'kah", description = "Wenn wir den Rush'kah bau'n, müss'n wir die Form des Loas nachbild'n, wie wir sie vor unsrem inner'n Auge seh'n. Wenn wir die Form des Loas kenn', versteh'n wir besser, wer sie sind. Doch die Maske wurde durch unsre Hände geformt. Wenn die Loa uns also seh'n, wissen sie, was wir erwart'n, das sie sind.\n\nWenn die Loa die Maske nicht segnen, dann erwart'n wir von ihnen, was zu sein, was sie nich' sind. Aber wenn die Loa die Maske segnen, dann gefällt ihnen, was wir in ihnen seh'n, und wir könn' verhandeln.\n\nWir könnt'n einfach 'nen Vertrag schreib'n, aber es is' einfacher, mit Wort'n zu lüg'n als mit den Händ'n.", sourceObjective = "Erstellt einen Rush'kah.", progress = "Das Rush'kah is' wichtig für die Verbindung zu den Loa.", completion = "Gute Arbeit, {name}!\n\nBin fast fertig mit meiner hier!", sourceObjectiveStatus = "unverified-source-field" }
quests[77900] = { id = 77900, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Loaprüfungen", description = "Wenn die Loa den Rush'kah segnen, beginnen die Prüfungen. Die Loa geben uns Aufgab'n, um uns zu lehr'n. Sobald die Prüfungen beginnen, hör'n sie für nichts und niemand'n auf!\n\nGeh'n wir zusammen zum Altar. Hexendoktorin Tzadah wird uns während des Rituals anweis'n. Sie ist Meister Gadrins Lehrling, hat aber wirklich Initiative gezeigt, bei der Prüfung zu helf'n.", sourceObjective = "Beginnt die Prüfung am Altar des Dunkelspeerloas.", completion = "Diese Prüfung is'... jetz' was andres. Normalerweise gewähr'n die Loa Visionen oder geb'n uns Aufgab'n, um uns zu lehr'n und sich mit uns zu verbind'n.\n\nStattdessen arbeit'n wir zusammen, um Mueh'zala aufzuhalt'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[77901] = { id = 77901, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück in die Schule", description = "Eure Hexendoktorin versucht, das Ritual zu wenden, um Mueh'zala zu ermächtigen. Viele werden von seiner Macht ergriffen werden, doch wir stehen nach wie vor an der Seite der Dunkelspeere.\n\nIch hatte eine andere Prüfung im Sinn, aber dann müssen wir uns eben anpassen. Befreit die anderen Trolle von seiner Opfermagie. Dieses Amulett wird ihnen helfen, doch zuvor müsst Ihr sie schwächen.\n\nVersucht, sie nicht zu opfern.", sourceObjective = "Extrahiert 8 Schatten von verlorenen Schülern, nachdem Ihr sie geschwächt habt.", completion = "Das verringert die Stärke des Rituals. Mueh'zala holt sich nich' noch mehr Dunkelspeere!", sourceObjectiveStatus = "unverified-source-field" }
quests[77902] = { id = 77902, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rituelle Rückgewinnung", description = "Diese Hexendoktorin hat die Prüfung gestohlen. Sie verhöhnt uns und versucht, die Lebenskraft anderer Lebewesen zu verzehren, um Mueh'zala zu befreien. Doch noch haben wir Einfluss darauf.\n\nGemeinsam können wir ihre bösen Kreise überwältigen. Wenn Ihr einen Kreis findet, dann ruft nach mir, und wir werden den Tod von dort vertreiben.", sourceObjective = "Entfernt 3 Ritualkreise mit Lukous Hilfe.", completion = "Wenn Ihr geg'n den Tod kämpft, is' Lukou 'ne gute Verbündete.", sourceObjectiveStatus = "unverified-source-field" }
quests[77903] = { id = 77903, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Macht des Todes", description = "Die Prüfung kann nich' aufgehalt'n werd'n, sobald sie begonnen hat, aber wir werden nich' zulass'n, dass Tzadah unsre Leute oder Loa dafür missbraucht, Mueh'zala zu helf'n.\n\nWenn wir nichts tun, könnt'n noch mehr Dunkelspeere dazu verleitet werd'n, in Mueh'zala Kraft zu find'n. Ich such nach 'nem Weg, um Tzadahs schützende Energie zu durchbrech'n. Haltet Ihr solange die Geister davon ab, Besitz von unsrer Heimat zu ergreif'n!", sourceObjective = "Tötet Mueh'zalas beschworene Geister.", completion = "Gute Arbeit mit dies'n Lakai'n. Das wird sie uns während dem, was uns noch erwartet, vom Hals schaff'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[77905] = { id = 77905, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Avatar von Mueh'zala", description = "Alles läuft auf dies'n Moment hinaus: Wir müss'n mit unsren Loa zusammenarbeit'n, um die Seele der Dunkelspeere zu rett'n.\n\nSchaut, ob Jani etwas find'n konnte. Hoffentlich bringt sein Gegenstand Euch nah genug an Tzadahs Abbilder, um sie zu zerstör'n. Dadurch sollt'n wir Gelegenheit erhalt'n, die Hexendoktorin selbst zu treff'n. Ich werde mit der Hilfe von Kevo ya Siti ihre Aufmerksamkeit auf mich lenk'n, aber passt auf ihre Wächter auf. Sie werd'n Euch nich' ohne Weiteres ihre Abbilder zerstör'n lass'n.", sourceObjective = "Holt Euch Janis Segen und begebt Euch anschließend mit Lukou zur Spitze der Säulen, um Tzadahs Schutztotems zu zerstören.", progress = "Tzadah is' 'ne Schande für die Dunkelspeere.", completion = "Wir hab'n Tzadah besiegt. Sie kann Mueh'zala nich' mehr bei dem Versuch unterstütz'n, aus seinem Gefängnis auszubrech'n.\n\nOhne die Hilfe der Loa hätt'n wir das nich' geschafft. Lukou, Kevo ya Siti und selbst Jani.", sourceObjectiveStatus = "unverified-source-field" }
quests[77906] = { id = 77906, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Loa der Dunkelspeere", description = "Das war keine traditionelle Prüfung, aber wir halt'n nur an Traditionen fest, wenn sie dem Stamm helf'n.\n\nDas ist unsre Stärke: uns drauf anzupassen, was uns erwartet.\n\nEs ist an der Zeit, die Vergangenheit loszulass'n und jene zu ehr'n, die uns am wichtigst'n sind. Die Dunkelspeere war'n nie der größte und auch nie der stärkste Stamm. Wir konnt'n besteh'n, weil wir unsren Pfad und unsre Verbündet'n sorgfältig gewählt hab'n.\n\nDie Loa und Ihr habt alle zusammengearbeitet und Euch aufgeopfert, nich' nur, um Bwonsamdi zu helf'n, sondern auch, um die Seel'n der Dunkelspeere zu beschütz'n. Deswegen würdig'n wir unsre Loa... und Euch.", sourceObjective = "Zerstört Mueh'zalas Altar und fügt Janis hinzu.", completion = "Die Dunkelspeere dienen 'nem Loa nich' nur, weil der Loa stark is'. Die Dunkelspeere dienen Loa, die auch ihrem Stamm dienen.\nDas is' genau das, was Lukou, Kevo ya Siti und Jani getan hab'n. Deswegen ehr'n wir sie nun.\n\nDie Maske, die Ihr gebaut habt, war nich' nur für die Zeremonie. Nehmt sie und die Gewandung unsres Stamms.\n\nTragt sie und wisst, dass Ihr 'n Mitglied der Dunkelspeere seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[77908] = { id = 77908, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Vermächtnis der Geheimnisse", description = "<Bringt das Buch zu Bobby Carlisle in Valdrakken, um beim Entziffern des Tafeltextes zu helfen!>", sourceObjective = "Bringt das Buch Tyrs Vermächtnis zu Bobby Carlisle in Valdrakken.", progress = "War meine Quelle brauchbar? Konntet Ihr das Buch finden?", completion = "Natürlich habt Ihr es gefunden! Also, Ihr habt wirklich das Zeug zu einem Feldermittler.\n\nTyrs Vermächtnis, hm? Interessant. Ich werde mit Kathos zusammenarbeiten, um zu sehen, ob wir den Text auf diesen Tafeln entziffern können. Ich bin mir sicher, dass dieses Buch der Schlüssel ist.\n\nWir sind so nah dran! Ich kann schon die Schlagzeilen sehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[77910] = { id = 77910, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verzaubertes Gebüsch", description = "Bestimmte Pflanzen des Smaragdgrünen Traums könnten Zutaten darstellen, die unserer Arbeit hier nützlich sein könnten. Aber wir brauchen viele von ihnen, und ich werde nicht irgendeinen Kräuterkundigen anstellen, um sie zu sammeln.\n\nIch habe eine Gießkanne verzaubert, die bei der Problemlösung helfen soll.\nReist in den Smaragdgrünen Traum und benutzt sie bei den Pflanzen, die ich brauche. Sie sollten sich dann selbst ausliefern.", sourceObjective = "Benutzt die Gießkanne bei 12 verzauberten Büschen.", completion = "Ausgezeichnete Arbeit, diese Pflanzen lassen den Ort wirklich aufblühen!", sourceObjectiveStatus = "unverified-source-field" }
quests[77911] = { id = 77911, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ins gemachte Bett", description = "Ich komme nicht zur Ruhe! Ich habe alle Energie im Kampf aufgebraucht, aber hier ist es zu laut und der Boden ist zu hart zum Schlafen...\n\nIch weiß! Es fällt mir nicht leicht, Euch zu bitten, aber ich muss mich erholen, damit ich weiterkämpfen kann.\n\nKönntet Ihr für mich zwei Fliegen mit einer Klappe schlagen? Erledigt die wütenden Peitscher und bringt mir ihre Blätter, damit ich mir ein Bett daraus bauen kann.", sourceObjective = "Sammelt 6 samtige Peitscherblätter von Peitschern.", progress = "Dafür, dass das hier der Smaragdgrüne Traum ist, ist es ganz schön chaotisch!", completion = "Danke für die Blätter. Hoffentlich kann ich so endlich schlafen.", sourceObjectiveStatus = "unverified-source-field" }
quests[77912] = { id = 77912, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unmoderner Schmuck", description = "Einige der hiesigen Juwelenschleifer wollen Exemplare der Verzierungen der Zaqalistämme studieren.\n\nDa sie gerade meine Heimat angreifen, sollten wir die Gelegenheit nutzen.\n\nKurz gesagt, nehmt sie ihnen doch mit Gewalt ab, ja?\n\nArgonax erwartet Euch, wenn Ihr sie gesammelt habt.", sourceObjective = "Sammelt 10 Zaqaliverzierungen.", progress = "Den seltsamsten Quellen kann neues Wissen entspringen.", completion = "Ich habe nicht so schnell damit gerechnet.\n\nIhr arbeitet schnell, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[77914] = { id = 77914, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brennende Runen", description = "Ich habe gehört, dass die Druiden der Flamme die Portale in den Traum mithilfe einer einzigartigen Art von Inschrift stabilisieren! Ihre Ziele sind schrecklich, aber ich kann nicht anders, als neugierig auf ihre Mittel zu sein.\n\nWenn wir ihre Methoden besser verstehen könnten, dann können wir unsere Verbündeten vielleicht auch besser auf ihren Ansturm vorbereiten. Wenn Ihr irgendwelche brennenden Runen in die Hände bekommt, bringt sie doch für das Studium zu meinem Kollegen.", sourceObjective = "Sammelt 10 brennende Runen von Druiden der Flamme im Smaragdgrünen Traum.", progress = "Gebt acht, Freund. Ich bezweifle, dass die Druiden der Flamme ihre Runen bereitwillig hergeben.", completion = "Ich danke Euch. Wir werden diese unverzüglich entziffern.\n\nDanke, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[77922] = { id = 77922, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flauschiger Füllungsfund", description = "Ich kann unmöglich ohne ein weiches Bett schlafen. Zum Glück gibt es im Traum derart weichen Salbei, dagegen sind sogar Rocfedern eine Beleidigung! Das wäre die perfekte Füllung!\n\nKönntet Ihr etwas Salbei in der Nähe sammeln, auf dem ich liegen kann?", sourceObjective = "Sammelt 8 Bündel seidiger Salbei.", progress = "Der Salbei sollte weich genug sein für einen bequemen Schlafplatz. Danke für Eure Hilfe.", completion = "Danke, dass Ihr mir diese Bettfüllung gebracht habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[77928] = { id = 77928, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sie hören immer zu", description = "Erinnert Ihr Euch an meinen Kontakt, Klaudia Huhu? Es scheint, als hätte sie eine andere Theorie darüber, wer hinter den Artefaktdiebstählen steckt.\n\nNachdem der letzte Tipp nichts ergab, bin ich ein bisschen abgespannt, aber einen Hinweis können wir nicht ablehnen. Die journalistische Redlichkeit verlangt, dass wir sie wenigstens anhören.\n\nIhr findet sie beim Friseursalon.", sourceObjective = "Sprecht mit Klaudia Huhu in der Nähe des Barbiers von Valdrakken.", completion = "So, dieses Mal bin ich mir sicher. Ich habe gegen jeden Einzelnen ermittelt. Ja, auch gegen Euch.\n\nTithris steckt hinter all dem. Er hat sich mit zwielichtigen Gestalten in der ganzen Stadt getroffen, um Vorräte für etwas ganz Großes zu sichern. Ich würde auf eine Expedition tippen.\n\nIhr müsst verschiedene Lagerorte seiner Ankäufe untersuchen. Ich habe die Koordinaten für die größeren Standorte notiert. Setzt die Denkkappe auf und los geht's! Und Euer Götze kann Euch helfen, die genauen Standorte einzugrenzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[77932] = { id = 77932, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wärme des Lebens", description = "Die Druiden der Flamme praktizieren krankhafte Magie, die alles verzerrt und verbrennt, was sie berührt. Aber sie haben auch ausgezeichneten Geschmack, was alchemistische Reagenzien betrifft.\n\nWenn Ihr etwas ihrer Verwandlungsasche findet, könntet Ihr sie für mich einsammeln? Einer meiner Kontakte im Traum hat nach dem Zeug gefragt.", sourceObjective = "Sammelt acht Proben Verwandlungsasche von den Druiden der Flamme im Qualmenden Gehölz.", progress = "Ah, da seid Ihr ja! Konntet Ihr ein wenig der Asche in die Finger bekommen? Ihre alchemistischen Eigenschaften sind wahrhaft wundersam.", completion = "Ah, wunderbar! Was ich hiermit alles erreichen kann... Man spaziert immerhin nicht einfach so in die Feuerlande!", sourceObjectiveStatus = "unverified-source-field" }
quests[77933] = { id = 77933, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blubbernde Funde", description = "Das Wachstum von Amirdrassil hat zahlreiche geologische Wunder im Traum aufgedeckt. Darunter eine Vielfalt magischer Quellen, aus denen Wasser aus dem tiefsten Inneren Azeroths sprudelt.\n\nReist in den Traum und sammelt Proben von diesen Quellen.", sourceObjective = "Sammelt 8 Proben von blubbernden Quellen.", completion = "Ich werde sie mit den anderen hier teilen, nachdem ich sie selbst untersucht habe.", sourceObjectiveStatus = "unverified-source-field" }
quests[77934] = { id = 77934, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein vollständiges Inventar", description = "<Stellt Notizen über die Lagerstandorte für Klaudia Huhu in Valdrakken zusammen.>", sourceObjective = "Berichtet Klaudia Huhu beim Friseursalon in Valdrakken von Euren Ergebnissen.\n\nBereitgestellter Gegenstand:", completion = "Hm, das ist nicht ungewöhnlich. Trotzdem bin ich überzeugt, dass er der gesuchte Drakonide ist. Warum sollte sich ein einfacher Gastwirt mit so vielen zwielichtigen Gestalten treffen?\n\nIch muss meine Daten noch einmal überprüfen und mir ansehen, was Ihr mir gebracht habt. Vielleicht fällt mir etwas auf.\n\nPasst auf Euch auf, {name}. Ich bin vielleicht paranoid, aber ich bin nicht blind. Uns läuft die Zeit davon.", sourceObjectiveStatus = "unverified-source-field" }
quests[77935] = { id = 77935, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwer-t beeindruckt", description = "Schwerter!\n\nVerzeiht, ich sah Euch und wollte es nicht vergessen.\n\nJa, wir brauchen Schwerter. Im Traum. Ihr könnt sie liefern, oder?\n\nBringt sie bitte zu Cylania.", sourceObjective = "Liefert 3 Drakoniumschwerter an Cylania im Smaragdgrünen Traum.", progress = "Kann ich Euch helfen?", completion = "Die werden wir sinnvoll einsetzen.\n\nDanke, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[77936] = { id = 77936, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine warme Ernte", description = "Jeder weiß, dass Hitze eine entscheidende Rolle in der Schmiedekunst spielt.\n\nIch habe gehört, dass der Smaragdgrüne Traum immer noch von den Verbündeten der Flamme heftig angegriffen wird. Es muss einen Weg geben, Brennstoff von diesen ewig feurigen Kreaturen zu bekommen.\n\nWenn Ihr irgendetwas findet, werden sich die Schmiede des Smaragdgrünen Traums bestimmt dafür interessieren.", sourceObjective = "Sammelt 10 Exemplare Essenz der endlosen Flamme im Smaragdgrünen Traum.", progress = "Hmm. Ja?", completion = "Ihr habt gefährliche Gegner bekämpft, um diese Materialien zu finden. Danke. Die werden uns bei der Herstellung unserer eigenen Gegenstände von gewaltigem Nutzen sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[77937] = { id = 77937, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verbotener Zucker", description = "Während dieser einzigartigen Blütezeit wurde eine neue Blume im Traum entdeckt. Diese bezaubernden Blumen produzieren bemerkenswerten Pollen. Ihr Aroma ist eine Freude, wie frisch gebackene Kekse.\n\nZum Leidwesen der Köche führt aber schon die kleinste Menge zu einer schweren Vergiftung der Leber.\n\nDoch für die Verzauberkunst ist es eine unglaubliche Universalzutat. In ersten Tests waren sie so potent wie die vierfache Menge chromatischen Staubs. Die Händler von Valdrakken haben großes Interesse daran.", sourceObjective = "Sammelt 8 Glühtropfenzucker von Schattenglühtropfen im Smaragdgrünen Traum.", progress = "Die Verzauberer hätten gerne mehr für ihre Tests. Sie müssen es weise einsetzen und prüfen. Wir hoffen, dass die Blume auch nach der großen Blüte bleibt, aber das kann niemand wissen.", completion = "Aah, ich dachte, Ihr würdet mir frische Kekse bringen! Aber das ist sogar noch besser.", sourceObjectiveStatus = "unverified-source-field" }
quests[77938] = { id = 77938, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine ungewöhnliche Ingenieurin", description = "Ich habe gehört, dass es eine legendäre Ingenieurin im Traum gibt, die die schönsten Traumfänger baut.\n\nDiese Ingenieurin, Nyla Buschschwanz liebt Morcheln mit Eichelgeschmack und braucht sie als Treibstoff für ihre Arbeit. Pilze mit Eichelgeschmack... Ziemlich seltsam, aber wohl nicht ganz unbekannt.\n\nEs gibt ein Küstengebiet in der Nähe des Auges von Ysera, wo diese Morcheln im Überfluss wachsen. Gebt aber in der Nähe der Wildtiere dort acht. Wenn diese Morcheln so schmackhaft sind, wie man sagt, werden sie gierig bewacht werden.", sourceObjective = "Sammelt 8 Weißklettmorcheln für Nyla Buschschwanz im Smaragdgrünen Traum.", completion = "<Nyla Buschschwanz, eine flauschige Fol'ya mit leuchtenden Augen, nimmt die Morcheln mit ihren kleinen Pfoten an. Sie verstaut sie mit fließenden und gezielten Bewegungen in einem Lager in der Nähe.\n\nDas muss die legendäre Ingenieurin sein, die Pilze mit Eichelgeschmack liebt. Jetzt ergibt alles einen Sinn.>", sourceObjectiveStatus = "unverified-source-field" }
quests[77945] = { id = 77945, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stiefel auf dem Boden", description = "Genau, wen ich gerade sehen wollte.\n\nIch habe einen Anforderungsschein für Lederartikel von einigen Bewohnern des Traums. Schuhe, natürlich. Zweibeiner scheinen die zu sammeln wie ein Eichhörnchen Nüsse, stimmt's?\n\nWenn Ihr sie habt, bringt sie bitte zu Cylania.", sourceObjective = "Liefert 3 Lederstiefel des Pioniers an Cylania im Smaragdgrünen Traum.", progress = "Kann ich Euch helfen?", completion = "Wunderbar, danke, {name}.\n\nMan kann nie genug Stiefel haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[77946] = { id = 77946, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Faseriger Faden", description = "Dünne Fäden mögen Euch eher an Schneiderei erinnern, aber sie können auch in der Lederverarbeitung sehr nützlich sein.\n\nEinige der widerstandsfähigeren Pflanzen des Traums können zu einem so starken Faden verarbeitet werden, mit dem sogar die dicksten Bälge und Häute vernäht werden können. Wenn Ihr auf Euren Reisen solche Fasern findet, bringt sie doch bitte meinem Kollegen im Traum.", sourceObjective = "Holt 1 Smaragdfasern von verzaubertem Dickicht im Smaragdgrünen Traum.", progress = "Macht Euch keine Sorgen um die Pflanzen selbst. Man kann ihnen kaum Schaden zufügen, und solange sie respektvoll behandelt werden, teilen sie ihre Früchte gerne mit Euch.", completion = "Ah! Das ist genau das, was ich brauche. Vielen Dank, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[77947] = { id = 77947, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Primalistenmode", description = "Ah, {name}, da seid Ihr ja!\n\nDie Roben der Primalisten sind ein interessantes Studienobjekt für die hiesigen Schneider. Wenn Ihr den Primalisten, die den Traum angreifen, einige abnehmen könntet, wäre ich sehr froh.\n\nZerreißt sie aber bitte nicht. Blutflecken sind optional. Die können wir rauswaschen.", sourceObjective = "Sammelt 10 Exemplare intakte Primalistenkleidung im Smaragdgrünen Traum.", progress = "Kann ich Euch helfen?", completion = "Magnolia hat erwähnt, dass Ihr einige Roben herbringen würdet.\n\nAh, sie hat auch erwähnt, dass sie vielleicht gewaschen werden müssen.\n\nDanke, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[77948] = { id = 77948, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausgebrannt", description = "Bitte, ich weiß, wie das aussieht, aber wir sind auf derselben Seite!\n\nMeine Geschwister und ich wollen gemeinsam der Flamme entsagen. Aber keiner von ihnen konnte entkommen oder sich mit mir treffen, seit ich geflohen bin, und seitdem sind Tage vergangen! Ich befürchte das Schlimmste.\n\nGlaubt Ihr, ich würde Euch um Hilfe anflehen, allein und unbewaffnet, wenn ich es nicht ehrlich meinen würde? Bitte, findet sie. Sie sind alles, was ich noch habe.", sourceObjective = "Findet Solarys' Geschwister im Qualmenden Gehölz.", completion = "<Solarys' Gesichtsausdruck wird von Trauer überschattet, als sie Eurer Erzählung zuhört.>\n\nLetzte Momente mit meiner Familie zu verbringen, ist mehr wert als eine Ewigkeit des Bedauerns. Das Leben selbst ist mehr wert als das, aber meine Bitte stieß auf taube Ohren.\n\nDanke, dass Ihr gerettet habt, was von meiner Familie noch übrig ist.\n\nEine der kleinen Kreaturen, die Kery'nael gerettet hat, scheint Euch ins Herz geschlossen zu haben. Bitte kümmert Euch um sie. Das ist das Mindeste, was wir dem armen Tierchen anbieten können.", sourceObjectiveStatus = "unverified-source-field" }
quests[77949] = { id = 77949, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Modische Federn", description = "Viele Wildtiere des Traumes haben Fell oder Federn. Was sie verlieren, seien es Haare oder Daunen, gilt als besonders haltbar, weich und modisch.\n\nDie Flugfedern der Schlummereulen sind besonders begehrt. Sie verlieren nicht häufig welche, und andere Tiere sammeln die Federn schnell für ihren Nestbau ein.\n\nIch habe gehört, die Verzweigten Wurzellande im Traum sind der beste Ort, um welche zu finden.", sourceObjective = "Sammelt 10 abgeworfene Flugfedern im Smaragdgrünen Traum.", progress = "Habt Ihr Federn gefunden? Sie sind leicht zu erkennen. Zwei Hände lang, meistens schneeweiß und butterweich.", completion = "Schneider auf der ganzen Welt werden erfreut sein, diese zu haben!", sourceObjectiveStatus = "unverified-source-field" }
quests[77953] = { id = 77953, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Sphäre in Gefahr", sourceObjective = "Hier ist die Nachricht, die sie geschickt haben. Irgendwas mit einer Kugel?\n\nKathos musste los, um nach etwas zu sehen, also könnt Ihr die Kugel zu mir bringen. Ich werde sie ihr nach ihrer Rückkehr aushändigen.\n\nPasst da draußen auf Euch auf. Oh, und nicht vergessen, all Eure nützlichen Werkzeuge mitzunehmen!", sourceObjectiveStatus = "unverified-source-field" }
quests[77954] = { id = 77954, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine merkwürdige Kugel", description = "<Tithris hat Euch gebeten, die Kugel zu ihm in Valdrakken zu bringen. Er wird sie Bewahrerin Kathos übergeben.>", sourceObjective = "Bringt die Kugel von Rathmus zu Tithris in Valdrakken.", progress = "Habt ihr meine Kugel? Äh, Kathos' Kugel meinte ich.", completion = "Perfekt. Kathos wird sich sicher sehr darüber freuen. Sie sagte, die Kugel wird bei Euren Ermittlungen helfen.\n\nAber da ist sie ja auch schon! Schön, dass sie sicher zurück ist. Ich werde ihr die Kugel geben, sobald ich was von hinten geholt habe.\n\nDanke für die Mühen, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[77955] = { id = 77955, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Randale um den warmen Ruhestein", description = "Halt, mein Ruhestein! Ich kann ohne meinen Ruhestein nicht schlafen.\n\nEin Djaradin hat ihn in unserem letzten Kampf gestohlen. Er bleibt immer warm und ich schlafe jede Nacht neben ihm.\n\nIch frage Euch das nur ungern, aber könntet Ihr mir meinen Ruhestein besorgen?\n\nDer Djaradin, der ihn gestohlen hat, müsste in der Nähe von Fyrakks Armee sein, gleich nördlich von hier.", sourceObjective = "Holt den warmen Ruhestein vom Steinwärmer zurück.", progress = "Meine Augen werden müde, doch mein Körper ist weiterhin wach...", completion = "Gah! Ich kann immer noch nicht einschlafen! Es ist mir peinlich, darum zu bitten, aber es gibt nur noch eine letzte Möglichkeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[77957] = { id = 77957, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein tückisches Rennen", sourceObjective = "Bobby und mir ist es endlich gelungen, die Tafeln zu entziffern. Sie berichten von einem Artefakt von gewaltiger Macht, das in Tyrhold versiegelt war. Und ich fürchte, das ist es, worauf Tithris aus ist.\n\nIhr müsst diese von den Tafeln beschriebene Macht vor Tithris sichern. Bobby und ich werden uns eine Wache schnappen und so schnell wie möglich nachkommen.\n\nNehmt unsere Notizen. Es gibt viele Sicherheitsvorkehrungen, die Ihr überwinden müsst, um zum Artefakt zu gelangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[77958] = { id = 77958, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schläfriger Druide im Smaragdgrünen Traum", description = "Warum kann ich immer noch nicht einschlafen, obwohl ich eine beheizte Decke habe?\n\n<Thaalean flucht und seufzt dann.>\n\nEs mag äußerst peinlich sein, aber meine Mutter hat mir früher in Teldrassil ein Schlaflied vorgesungen, bis ich eingeschlafen bin. Könnte ich Euch bitten, das auch zu tun?\n\nDas Schlaflied an sich ist nicht wichtig, ich will mich nur ausschlafen.", sourceObjective = "Singt ein Schlaflied für den schläfrigen Druiden.", completion = "Ich danke Euch vielmals, dass Ihr bei meinen Freunden nach dem Rechten gesehen habt.\n\nWenn sie wieder erwachen, werden sie erneut bereit sein, gegen Fyrakks Truppen zu kämpfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[77976] = { id = 77976, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unterstützt das Abkommen: Traumsprung", description = "Eine Gruppe Druiden aus ganz Azeroth hat sich versammelt, um einen plötzlich im Smaragdgrünen Traum aufgetretenen Energieschub zu untersuchen.\n\nDas könnte uns alle betreffen, {name}. Bitte helft ihnen in ihrem Bestreben, dieses neue Phänomen zu verstehen.", sourceObjective = "Trefft die Druiden, die den Traumsprung untersuchen, und sammelt hundert Traumsprungvereinigung. Führt Eure Bemühungen fort, dem Valdrakkenabkommen und seinen Verbündeten auf den ganzen Dracheninseln zu helfen.", completion = "Danke für Eure Unterstützung, {name}. Wir müssen diesen Traumsprung bei seiner Entwicklung genau beobachten.", sourceObjectiveStatus = "unverified-source-field" }
quests[77977] = { id = 77977, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein ominöses Artefakt", description = "<Eine Kugel würde perfekt auf die Konsole passen.>", sourceObjective = "Sichert die Kugel von Rathmus und das darin verborgene Artefakt.", progress = "Eine Truhe! Sie war die ganze Zeit über in Tyrhold eingeschlossen. Darf ich sie untersuchen?", completion = "Der Text oben auf dieser Truhe ist definitiv in Titanensprache verfasst. Aber das hier ist eine Sprache, die von der Brennenden Legion verwendet wird! Und dieser Text wird von den Dienern der Alten Götter benutzt. Ich habe noch nie gesehen, dass diese drei Sprachen so miteinander vermischt werden.\n\nIch beherrsche die Sprache der Titanen nicht so gut, aber da wird eine Gefahr im Inneren der Truhe erwähnt. Ein Gegenstand? Oder vielleicht einfach nur... Wissen.\n\nIch werde dafür sorgen, dass die Truhe gesichert und untersucht wird. Danke nochmals, {name}. In meinen Augen seid Ihr mittlerweile ein würdiger Bewahrer.", sourceObjectiveStatus = "unverified-source-field" }
quests[77978] = { id = 77978, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine weitergereichte Fackel", description = "<Strategische Dokumente liegen überall um Lyandris verteilt. Die meisten davon handeln von Experimenten und zukünftigen Angriffszielen.>\n\n<Es wäre für Eure Verbündeten äußerst nützlich, weitere dieser Dokumente zu finden. Und die Reihen der Flamme zu lichten, kann auch nicht schaden.>", sourceObjective = "Sammelt Dokumente und tötet Druiden der Flamme im Qualmenden Gehölz.", progress = "Was gibt es?", completion = "Lyandris hat all das gerettet? Und Ihr... Ihr habt beendet, was sie begonnen hat.\n\nIch danke Euch, dass Ihr mir ihr Tagebuch zurückgebracht habt. Behaltet die Dokumente. Sie werden Euch und Euren Verbündeten wertvolle Informationen liefern.\n\nFür mich wären sie nur eine düstere Erinnerung.", sourceObjectiveStatus = "unverified-source-field" }
quests[77982] = { id = 77982, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Habgierige Gessie" }
