quests[77988] = { id = 77988, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Test", description = "Wenn es ums Gewinnen geht, können Bronzewelpen leichtsinnig werden, also passt auf die Zeitwege auf!\n\n: Verwandelt in ein ausgewachsenes Exemplar und erhöht die Geschwindigkeit.\n: Stellt 1 Elan wieder her, bis sämtlicher Elan wiederhergestellt ist.\n: Setzt Abklingzeiten zurück.", sourceObjective = "Helft Zhusadormu, durch die Ringe zu gleiten.", sourceObjectiveStatus = "unverified-source-field" }
