quests[78002] = { id = 78002, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf die Probe stellen: Konzentriertes weises Pergament", description = "Die Ordnungsmagie und Schattenflammenmagie ringen miteinander. Die Verzauberung wird niemals in der Lage sein, Fyr'alaths Macht zu leiten, wenn wir die überschüssige Ordnungsmagie, die abgestoßen wird, nicht kanalisieren können.\n\nWenn Ihr die Verzauberung kanalisieren könnt, können Eure Verbündeten die überschüssige Ordnungsmagie auffangen.", sourceObjective = "Gebt die überschüssige Ordensmagie zurück in Shalasars weises Pergament.", completion = "Harte Arbeit, aber voll und ganz lohnend. Setzt dieses Pergament gut ein.", sourceObjectiveStatus = "unverified-source-field" }
quests[78003] = { id = 78003, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handhabung: Straffe Haltespule", description = "Ich habe von einer Wurzel im Smaragdgrünen Traum gelesen, die für ihre defensiven Eigenschaften bekannt ist. Sie bindet ihre Ranken an mächtige Gegner, um die umgebende Flora und Fauna zu beschützen. Ein befreundeter Schreiber könnte in der Lage sein, ihre Eigenschaften zu nutzen.\n\nWenn ich nur Proben dieser Wurzel in die Finger bekommen könnte, wäre ich sicher in der Lage, ihre Eigenschaften zu bestimmen und daraus etwas zu erschaffen, das Fyr'alaths Macht binden kann.\n\nHier sind meine Notizen. Ihr solltet in der Lage sein, mächtige Kreaturen zu finden, die Flecken wilder Haltespule bewachen. Gute Jagd.", sourceObjective = "Sammelt straffe Haltespule von mächtigen Gegnern im Smaragdgrünen Traum.", progress = "Ah, danke, dass Ihr mir diese bringt.", completion = "Beeindruckend! Ihr seid wirklich hartnäckig.\n\nJetzt können wir die Basis unserer Bindungsrune fertigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[78015] = { id = 78015, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feuerbrand Fystia" }
