quests[78040] = { id = 78040, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Scherbenweltpokal beginnt", description = "<Himmelsreiter/Himmelsreiterin>! Ihr habt Lord Andestrasz gerade verpasst. Er ist auf der Suche nach fähigen Himmelsreitern wie Euch, die sich in den neuen Rennen messen!", sourceObjective = "Sucht Lord Andestrasz in Valdrakken auf.", completion = "Danke für Euren Besuch, Drachenreiter!", sourceObjectiveStatus = "unverified-source-field" }
quests[78041] = { id = 78041, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zorn der Himmelsmutter", description = "Wir haben Berichte erhalten, dass die Druiden der Flamme einen weiteren Sammelpunkt direkt südlich vom Auge von Ysera errichtet haben.\n\nZu ihrem Unglück hat dieser Punkt die örtlichen geflügelten Wesen gestört und den Zorn der Schwarmmutter geweckt.\n\nSprecht mit Aviana und geht ihr zur Hand. Wir werden ihre Augen und Schwingen im kommenden Kampf brauchen.", sourceObjective = "Sucht Aviana auf.", completion = "Ich hatte schon erwartet, dass Cenarius irgendwann Unterstützung schicken würde.\n \nAber dieser närrische bodenbewohnende Loa?\n\n<Aviana tippt genervt mit einer Kralle auf, als sie Q'onzu von der Seite anfunkelt.>", sourceObjectiveStatus = "unverified-source-field" }
quests[78042] = { id = 78042, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Avianas Einschätzung", description = "<Avianas Augen verengen sich, als sie die Druiden der Flamme weit unter Euch beobachtet.>\n\nQ'onzu mag sich damit abfinden, dass diese Ketzer das Gewebe des Traums selbst zerstören, aber ich nicht.\n\nBringt mir als Beweis Eurer Taten Fetzen ihrer Rüstung, bedeckt von ihrem Blut.\n\nHaltet Euch nicht zurück, {name}. Erinnert Euch daran, zu was diese Heiden fähig sind.", sourceObjective = "Sammelt 20 blutige Rüstungsfetzen.", progress = "Jede Minute, in der sie unbehelligt bleiben, geht ein weiterer Teil des Traums durch ihre schändlichen Taten verloren.", completion = "Taten sprechen lauter als Fragen, Champion.\n\nDenkt daran, wenn Eure Beute das nächste Mal Eure Heimat angreift.\n\n<Aviana wirft Q'onzu einen finsteren Blick zu.>", sourceObjectiveStatus = "unverified-source-field" }
quests[78043] = { id = 78043, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Q'onzus Dilemma", description = "Ihr schon wieder! Nun, Ihr müsst hier sein, um zu helfen, richtig?\n\nGanz sicher seid Ihr das. Warum auch nicht? Das ist eine so aufregende Entwicklung. Was könnten diese jämmerlichen Druiden vorhaben?\n\nZum Glück haben einige meiner Freunde die Druiden infiltriert. Ich bin sicher, dass sie eine beeindruckende Geschichte zu erzählen haben.\n\nVorwärts, <mein neugieriger Kumpan/meine neugierige Kumpanin> und kommt mit aufregenden Neuigkeiten zurück!", sourceObjective = "Sprecht mit dem flammengetarnten Traumkin, um Informationen über die Druiden der Flamme zu erhalten.", completion = "Also, das IST interessant, nicht wahr?\n\n<Q'onzu erzittert und tippelt aufgeregt auf der Stelle.>\n\nDas muss Euch doch auch faszinieren, {name}?\n\nAch, wie dumm von mir. Natürlich tut es das!", sourceObjectiveStatus = "unverified-source-field" }
quests[78044] = { id = 78044, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die qualvollen Pollen", description = "Dieser Glutpollen ruft keinen interessanten Wandel hervor. Er verschlingt alles, bis nichts außer Asche bleibt. Er bringt... Einheitlichkeit.\n\nUnd ich finde das tragisch schal.\n\nIch befürworte jeden Wandel, unabhängig von seiner Herkunft. Aber wenn DIESER Wandel alle zukünftigen Möglichkeiten für weitere Veränderungen behindert, muss er aufgehalten werden.\n\nWenn Kreaturen des Traums mit diesem Pollen infiziert wurden, müssen sie ausgelöscht werden. Das ist keine Flamme, der wir die Ausbreitung erlauben dürfen.", sourceObjective = "Enthüllt und tötet 10 Glutpollenbestien.", completion = "Man bedenke nur, welchen Aufwand diese Agenten der Monotonie betreiben mussten, um mich, MICH, DEN LOA DER VERÄNDERUNG, dazu zu bringen, mich in ihren Traumverändernden Plan einzumischen.\n\nSo eine Unverschämtheit!", sourceObjectiveStatus = "unverified-source-field" }
quests[78045] = { id = 78045, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Ursache beseitigen", description = "<Avianas Blick ruht für einen Moment mit gerunzelter Stirn auf Q'onzu.>\n\nObwohl ich Q'onzus Faszination für die Veränderung nicht teile, hat das endlose Nachfragen doch einen weiterreichenden Plan aufgedeckt, als wir ursprünglich vermuteten.\n\nDie Tiere zu töten wird nicht viel bringen, wenn wir nicht die Wurzel des Problems jäten.\n\nFindet brennenden Aschphodill im Hain und reißt ihn heraus.", sourceObjective = "Sammelt 8 entwurzelte Aschphodille.", progress = "Wenn diese Aschphodille ihre üblen Pollen ungehindert verbreiten können, ist der Rest des Traums in großer Gefahr.\n\n<Aviana verzieht das Gesicht.>", completion = "Gut gemacht, {name}.\n\nIch werde dafür sorgen, dass Cenarius von den Schäden erfährt, die dieses Unkraut angerichtet hat. Ein paar Dryaden sollten in der Lage sein, sich um den übrigen Pollen und alle Blumen zu kümmern, die Ihr vielleicht übersehen habt.\n\n\n\nNun bleibt nur noch eine Aufgabe, Champion.", sourceObjectiveStatus = "unverified-source-field" }
quests[78046] = { id = 78046, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufseher-Beaufsichtigung", description = "Diese Forschungsnotizen, die Ihr Q'onzu mitgebracht habt, erwähnen diejenigen hinter diesen üblen Experimenten.\n\nIhr Aufseher, mit dem Namen Chardryn, war die ganze Zeit direkt unter unserer Nase.\n\nEr beaufsichtigt ihre Forschungsstation unter uns.\n\nWenn wir seine schrecklichen Experimente ein für alle Mal beenden und den Fortschritt unserer Feinde zunichtemachen wollen, müssen wir an ihm ein Exempel statuieren.", sourceObjective = "Tötet Aufseher Chardryn.", progress = "Wenn Chardryn und seine wahnsinnigen Kräuterkundler hier im Traum biologische Kriegsführung beginnen können, dann schweben Amirdrassil und ganz Azeroth in Gefahr.\n\nWir können diese Speichellecker des Feuers nicht weiterleben lassen.", completion = "Also ist ihr Aufseher tot?\n\n<Aviana nickt euch anerkennend zu.>\n\nGut.\n\nNachdem Chardryn fort ist, ihre Experimente zerstört sind und ihre Forschung gestoppt wurde, können wir endlich hoffen, dass dies das Ende ihrer verderbten Pläne ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[78047] = { id = 78047, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Strecken des Scherbenweltpokals", description = "Es ist an der Zeit, Euren Mut wieder auf die Probe zu stellen.\n\nMeine Bronzekollegen sind in die Scherbenwelt gereist, um weitere Herausforderungen bereitzustellen. Wir würden gerne sehen, ob mutige Himmelsreiter alle Strecken abschließen können!\n\nSeid Ihr bereit?", sourceObjective = "Fliegt durch die Strecken des Scherbenweltpokals.", progress = "Habt Ihr Euch heute schon in die Lüfte geschwungen?", completion = "Ihr seid Euren Drachenreiterkollegen voraus! Wenn Ihr es noch nicht getan habt, könnt Ihr Eure Zeiten des Scherbenweltpokals verbessern und Euch die Farben der Reiter von Azeroth verdienen.", sourceObjectiveStatus = "unverified-source-field" }
quests[78064] = { id = 78064, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Q'onzus Wahrnehmung", description = "Ihr habt viele Fragen und ich viele Sorgen.\n\nSolch drängende Sorgen. Ein Eindringling, ein unhöflicher Störenfried unseres wunderbaren Tags. Wie sehr ich mich sorge. Wenn sich doch nur jemand dieses Eindringlings annehmen könnte.\n\nWartet, Ihr könntet das für mich tun! Das ist gleich auf zweierlei Arten lohnend, Ihr kümmert Euch um den Eindringling und ich beantworte Eure Fragen. Ich habe den Eindringling zu einer Höhle im Norden verfolgt. Ihr seid ihm sicherlich gewachsen.", sourceObjective = "Findet und stellt den Eindringling in Q'onzus Nest.", progress = "Ich kann den Eindringling spüren, der mein Nest stört!", completion = "Ha! Ach, seid nicht so. Das war lustig. Schaut nicht so wütend drein.", sourceObjectiveStatus = "unverified-source-field" }
quests[78065] = { id = 78065, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Q'onzu-Querelen", description = "Champion, wie ich höre, konnten wir Q'onzu nicht überzeugen, sich uns anzuschließen. Allerdings brauchen wir jede Hilfe, die wir kriegen können.\n\nIhr müsst in Erfahrung bringen, warum Q'onzu uns nicht helfen will, und etwas Überzeugungsarbeit leisten. Wir haben eine recht angestrengte Beziehung, Q'onzu und ich. Ihr habt bestimmt mehr Erfolg.\n\nWie ich hörte, hat Q'onzu in der Nähe des Schauderschnapphains ein kleines Nest gebaut. Würdet Ihr dort hingehen?", sourceObjective = "Nähert Euch Q'onzu erneut und fragt, was vor sich geht.", completion = "Q'onzu sagte, dass jemand zu Besuch kommen würde. Ich hoffe, Ihr bringt Opfergaben?", sourceObjectiveStatus = "unverified-source-field" }
quests[78066] = { id = 78066, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Antworten, die Ihr verdient habt", description = "Ah, das ist viel besser. Jetzt kann ich nachdenken.\n\nWas wolltet Ihr noch gleich? Oh ja! Fragen.\n\nStellt sie nur, wenn es sein muss.", sourceObjective = "Erhaltet Antworten zu Q'onzu.", completion = "<Q'onzu ist mit allen Anhängern verschwunden. Das muss die Antwort sein, die Euch nach Meinung von Q'onzu zustand.\n\nVorerst zumindest.>", sourceObjectiveStatus = "unverified-source-field" }
quests[78068] = { id = 78068, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Bitte eines Konstrukteurs", description = "{name}, ich habe etwas von Großkonstrukteur Romuul für Euch erhalten.\n\nRomuul möchte, dass Ihr Euch die Nachricht anhört, bevor Ihr Euch zur Exodar begebt.", sourceObjective = "Sucht Großkonstrukteur Romuul auf der Exodar auf.", completion = "Entschuldigung, dass ich Euch so kurzfristig hergebracht habe, {name}, doch Eure Hilfe käme uns momentan sehr gelegen.\n\nMan hat mir zahlreiche überraschende Fristen gesetzt.\n\n\"Überraschend\" und \"Fristen\" sind zwei Wörter, die ich nicht gerne im selben Satz sehe.", sourceObjectiveStatus = "unverified-source-field" }
quests[78069] = { id = 78069, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tradition wiederaufleben lassen", description = "Der Prophet wollte Euch persönlich um Hilfe mit dem Tishamaat bitten, doch da er gerade an anderer Stelle beschäftigt ist, habe ich Euch gefragt, um unseren Auftrag schneller ins Rollen zu bringen.\n\nMeine Kollegen und ich arbeiten an einem besonderen Projekt. Und da der Prophet heute das Tishamaat ausgerufen hat, werden wir es während der Feierlichkeiten enthüllen!\n\nDafür brauche ich den Emitter, der eigentlich überarbeitet werden müsste. Wir haben allerdings nur kurz Zeit zum Löten.\n\nBesorgt etwas Glühfaden und ein Lötwerkzeug aus den Kisten in der Umgebung, {name}. Dann kann ich ihn möglicherweise verdrahten.", sourceObjective = "Helft Romuul, die Reparatur des holografischen Emitters zu beenden.", progress = "Ich bedauere es, in einer Zeit wie dieser keine Lehrlinge zu haben.", completion = "<Romuul wackelt probehalber am neu eingesetzten Kristall.>\n\nNicht meine beste Arbeit, aber es wird reichen.\n\nSo es das Licht will, wird er funktionieren, bis unser Projekt enthüllt wird und die Feier vorüber ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[78070] = { id = 78070, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dringende Termine", description = "Im Verlauf dieses Tishamaat werden Ataanya und ich die Baupläne unserer Projekte vorstellen.\n\nAtaanya ist Oberste Konstrukteurin Shattraths. Ihr Vater war mein Mentor, der berühmte Exarch Hataaru.\n\nEs ist kein Leichtes, in Hataarus Hufstapfen zu treten, doch Ataanya hat sich mehr als bewiesen.\n\nSie hat die Baupläne und sollte hier sein, wenn sie vorgestellt werden, doch sie antwortet nicht auf meine Nachrichten.\n\nAtaanya verlässt die Stadt nur selten, doch für das Tishamaat wird sie sicherlich eine Ausnahme machen können. Vielleicht könnt Ihr sie ja überzeugen.", sourceObjective = "Sprecht mit Ataanya in Shattrath.", completion = "Ich habe einen Datenkristall vorbereitet. Die Baupläne befinden sich darauf.\n\nMein Lehrling kann ihn Euch heraussuchen.\n\nIch habe keine Zeit, um Shattrath zu verlassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[78071] = { id = 78071, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eilauftrag", description = "Meine Baupläne sprechen für sich selbst.\n\nJede Kalkulation wurde bestätigt. Sie respektieren jegliche Konstruktionsvorschrift. Ich habe sogar einen Plan der Kanäle beigelegt, denen die Energieversorgung folgen muss.\n\nRomuul kennt das Projekt. Er hat bereits alles abgesegnet. Er ist selbst in der Lage, es den Massen zu erklären.\n\nIch muss meine kostbare Zeit nicht damit verschwenden, für diesen lächerlichen Feiertag zur Exodar zu reisen.\n\nMein Lehrling wird Euch die Baupläne auf einem Datenkristall geben. Nehmt ihn und geht.", sourceObjective = "Sprecht mit Beruun. Vielleicht weiß er, wie wir Ataanya dazu überreden können, Shattrath zu verlassen.", progress = "Wir werden für Ataanya tun, was wir können.", completion = "Hm, es war einen Versuch wert.\n\nOffenbar wird es schwierig, sie zum Tishamaat zu bekommen...\n\nAber da fällt mir noch etwas ein.", sourceObjectiveStatus = "unverified-source-field" }
quests[78072] = { id = 78072, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine alte Wunde", description = "<Beruun flüstert Euch zu.>\n\nSicherlich wisst Ihr bereits, dass es für die Draenei Wege gibt, mit den Verstorbenen zu sprechen.\n\nEs ist nicht das Gleiche, wie die geliebte Person wiederzuhaben, aber...\n\nHataarus Asche wurde nach Auchindoun gebracht, nachdem die Seelenpriester den Tempel zurückerobert hatten. Vielleicht kennen sie einen Weg, wie wir Ataanya dabei helfen können, mit ihrem Verlust umzugehen?", sourceObjective = "Sprecht mit den Seelenpriestern in Auchindoun.", completion = "Es ist schön, Besucher zu haben!\n\nDie geehrten Toten hier werden gut umsorgt, aber nicht viele reisen hierher, um Zwiesprache mit ihnen zu halten.\n\nIhr Tod kann eine schmerzhafte Erinnerung daran sein, was die {race} erdulden mussten.", sourceObjectiveStatus = "unverified-source-field" }
quests[78073] = { id = 78073, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bleibende Narben", description = "Ich glaube, wir können helfen.\n\nAber vielleicht könnt Ihr zuerst mir helfen...\n\nAls uns die Nachricht erreicht hat, dass das Tishamaat ansteht, haben wir uns beeilt, unsere am stärksten gepeinigten Geister für die Reise zur Exodar vorzubereiten. Die Sakramente der Feierlichkeiten können ihnen möglicherweise dabei helfen, in Frieden zu ruhen.\n\nSie müssen jedoch zustimmen, bevor wir sie transportieren können. Wir müssen also zunächst Zwiesprache mit ihnen halten und sie beruhigen.\n\nHelft Ihr uns dabei, diese Geister zu besänftigen? Danach bringe ich Euch an den Ort, wo Hataaru beigesetzt wurde, und gebe Euch, wonach Ihr sucht.", sourceObjective = "Helft Exarch Maladaar, Zwiesprache mit den Geistern von Auchindoun zu halten und sie zu besänftigen.", completion = "Danke dafür, was Ihr getan habt, {name}.\n\nWenn die sterblichen Überreste eines Geistes bewegt werden, kann ihn das sehr aufbringen. Wir müssen ihn beruhigen, damit seine Gebeine ihre Reise sicher antreten können.", sourceObjectiveStatus = "unverified-source-field" }
quests[78074] = { id = 78074, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durchblick", description = "Glücklicherweise leiden nicht alle Gefallenen, die hier in Auchindoun begraben liegen, wie diese drei hier. Manche entschlafen einfach sanft wie Erde, die sich nach einem Regenschauer setzt.\n\nExarch Hataaru ist eine solche Seele. Dem Licht sei Dank, dass er ruhig schlummert.\n\nKommt, ich führe Euch zu seiner Gruft.", sourceObjective = "Sucht das Grab von Exarch Hataaru auf und kehrt dann zu Ataanya in Shattrath zurück.", progress = "<Ataanya verschränkt ihre Arme dicht an ihrem Körper und sieht weder Euch noch Beruun an.>", completion = "Na gut...\n\n<Ein Augenblick lang scheint sie Euch die Linse wegschnappen zu wollen. Stattdessen nimmt sie sie Euch sanft ab.>", sourceObjectiveStatus = "unverified-source-field" }
quests[78075] = { id = 78075, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bewegende Vergangenheit", description = "Meine Mutter starb auf einem Kolonieplaneten. Mein Vater und ich stützten uns gegenseitig, um darüber hinwegzukommen. Aber dann kam er während der Belagerung von Shattrath um, während er zusah, wie die Mauern seiner größten Errungenschaft zu Staub zerfielen... \n\nDanach war niemand mehr für mich da.\n\nDeshalb stürzte ich mich in die Arbeit. Und jetzt habe ich die Pläne für mein eigenes Shattrath. Ein besseres Shattrath.\n\n<Ataanya ballt eine Faust um die Linse und atmet dann resignierend aus.>\n\nIch gehe zur Exodar, aber wenn Romuul nur ein Wort darüber verliert, lasse ich ihn seinen Lötkolben fressen.", sourceObjective = "Kehrt zu Großkonstrukteur Romuul auf der Exodar zurück.", completion = "Auf gewisse Weise war es schwieriger, Ataanya hierherzubekommen, als Antorus zu Fall zu bringen und zu besiegen.\n\nSpaß beiseite: Ich bin froh, dass sie da ist. Ich wusste, dass das Tishamaat nicht leicht für sie sein würde. Ihr Vater war ein großer Mann, und wir alle betrauern seinen Tod.\n\nDieses Tishamaat wird langsam zu einem unserer Holo-Rekorde!\n\n<Romuul senkt vertrauensvoll seine Stimme.>\n\nSogar Hatuun ist da!", sourceObjectiveStatus = "unverified-source-field" }
quests[78076] = { id = 78076, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Notmaßnahmen", description = "{name}! Velen sagte mir, ich würde Euch hier finden. Er braucht Eure Unterstützung.\n\nDie Satyrn, die eine Insel in der Nähe befallen haben, überfallen Draenei auf dem Weg zum Tishamaat.\n\nVelen und ich versuchen, das Problem still und leise zu lösen. Er möchte an einem Tag des Sakraments nicht die Verteidiger mobilisieren und damit sein Volk in Aufruhr versetzen.\n\nDoch trotz unserer Bemühungen gehen die Angriffe weiter. Wir sind vielleicht gezwungen, das Fest abzusagen, wenn wir diese Dämonen nicht unter Kontrolle bringen.\n\nKommt mit mir, damit wir dieser Bedrohung ein Ende setzen können.", sourceObjective = "Nutzt den Manarochen von Argus, um mit Häuptling Hatuun zur Blutmythosinsel zu fliegen.", completion = "Ich hatte gehofft, etwas gegen die plötzlichen Angriffe der Satyrn unternehmen zu können, bevor ich das Tishamaat offiziell für alle verkünde...\n\nDaher bin ich dankbar, dass Romuul Euch früh genug zur Exodar gerufen hat.\n\nIch vermute, dass Hatuun Euch die Lage erläutert hat?", sourceObjectiveStatus = "unverified-source-field" }
quests[78077] = { id = 78077, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unter die Haut", description = "Arzaal und ich sind derselben Meinung. Wir müssen herausfinden, wie stark diese Satyrn sind, bevor wir versuchen, sie gewaltsam zu vertreiben, sonst nehmen wir einen Kampf auf, den wir nicht gewinnen können.\n\nIch lerne viel über meine Gegner, indem ich beobachte, welche Schäden sie hinterlassen.\n\nDie Fauna hier wurde ganz klar durch die Restenergie der Exodar verderbt, doch ich vermute, dass die Gegenwart der Dämonen alles noch verschlimmert hat.\n\nSammelt Knochen der hiesigen Wildtiere für mich. Sie zu studieren, könnte uns Hinweise geben.", sourceObjective = "Sammelt 8 hohle Knochen von verderbten Wildtieren.", progress = "Denkt daran, dass Ihr sie von ihrem Leiden erlöst.", completion = "<Hatuun zerbricht einen der Knochen, schnüffelt vorsichtig am schäumenden Mark und runzelt die Stirn.>\n\nNiedere Dämonen verderben Kreaturen nicht so tief. Ihre teuflische Krankheit kann kaum die Hautbarriere durchdringen und schon gar nicht die Knochen oder die Seele.\n\nWir haben es hier nicht mit schwachen Wichteln zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[78078] = { id = 78078, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feindeinschätzung", description = "Die Legion mag nur ein Wesen sein, doch es ist riesig. Die Dämonen, aus denen sie sich zusammensetzt, sind so verschieden wie die zahllosen Welten, die sie erobert haben.\n\nAber ich hatte noch keinen Umgang mit Satyrn. Aus den Erzählungen des Propheten schließe ich, dass sie nicht gut organisiert, allerdings durchaus intelligent und ungezähmt in ihrer Böswilligkeit sind.\n\nIch bin geneigt zu glauben, dass ihre jüngsten Angriffe zufällig sind, aber vielleicht ist dem gar nicht so. Bringt mir die Totems, die sie auf der Blutmythosinsel verteilt haben. Vielleicht kann ich aus ihnen ableiten, welches höhere Ziel sie verfolgen, wenn sie überhaupt eines haben.", sourceObjective = "Sammelt 6 Satyrtotems.", progress = "Ich würde gerne über die Fähigkeiten der Satyrn Bescheid wissen, bevor ich sie angreife.", completion = "Interessant.\n\nDiese Kristalle scheinen die gleichen zu sein wie die, die der Blutmythosinsel entspringen, aber offenbar sind sie absichtlich auf diesen Totems platziert worden.\n\nIch werde sie weiter untersuchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[78079] = { id = 78079, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausmerzung", description = "Ich kann die Draenei nicht guten Gewissens für das Tishamaat zusammenkommen lassen, wenn wir so nah an unserem Zuhause bedroht werden.\n\nWenn einer der Man'ari die Satyrn nutzt, um diese Angriffe zu arrangieren oder uns von einem bösen Spiel abzulenken, müssen sie sofort ausgemerzt werden.\n\nWir werden getrennt nach Spuren des Gegners suchen. Arzaal kümmert sich um das nördliche Lager der Satyrn. Ihr, Hatuun und ich sehen uns das näher gelegene Lager an.", sourceObjective = "Trefft Euch mit Velen und Hatuun in Nazzivian, um nach Anzeichen von Man'ari in der Gegend zu suchen.", completion = "Wir haben die verantwortlichen Man'ari noch nicht gefunden, aber wenn wir es tun, werden sie dafür bezahlen.", sourceObjectiveStatus = "unverified-source-field" }
quests[78080] = { id = 78080, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An der Quelle", description = "Könnt Ihr das hören? Die Stille?\n\nDie Gegend ist verlassen. Nicht einmal das tollwütige Wild wagt es, sich dem Lager zu nähern.\n\nIch sehe keine unmittelbare Ursache, doch die teuflische Resonanz hier ist fast überwältigend. Ich spüre, dass sie von den Händen der Man'ari gewirkt wurde, aber etwas hindert mich daran, sie genauer zu untersuchen.\n\nIrgendetwas wird dort versteckt.\n\nEs muss die Tarnmagie sein, die Hatuun aus dem anderen Lager gemeldet hat, die mich blockiert. Ich kann sie bannen, aber nicht sagen, was wir finden werden, wenn ich das tue.", sourceObjective = "Entdeckt die Quelle der teuflischen Konzentration in Axxarien und zerstört sie.", progress = "Genug ist genug!", completion = "Es ist vollbracht.\n\nIch hätte nie gedacht, dass die Bedrohung auf der Blutmythosinsel so groß werden könnte.\n\nDem Licht sei Dank, dass ich mich entschieden hatte, Hatuun und Arzaal herzubringen. Ohne sie... ohne uns alle... wäre dies hier nicht möglich gewesen.", sourceObjectiveStatus = "unverified-source-field" }
quests[78081] = { id = 78081, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schmerz lässt nach", description = "Sironas wurde erneut getötet, und die Blutmythosinsel kann nun endlich heilen. Ihr Einfluss hatte zweifelsohne die Verderbnis an dieses Land gebunden.\n\nDas ist ein weiterer Grund, heute zu feiern, allerdings nicht der wahre Grund, warum ich Hatuun und Arzaal nach Azeroth gerufen habe.\n\nSie sollten mit uns am Tishamaat teilnehmen.\n\nDas Sakrament verlangt von uns, über die Vergangenheit nachzudenken und uns um eine bessere Zukunft zu bemühen. Unser gemeinsames Vorgehen versinnbildlicht das.\n\nIch werde sie zur Exodar bringen. Stoßt bitte zu uns, sobald Ihr bereit seid.", sourceObjective = "Trefft Euch mit Prophet Velen auf der Exodar.", completion = "Es erfüllt mich mit großer Freude, die Eredar endlich versammelt zu sehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[78082] = { id = 78082, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine geteilte Last", description = "Das Tishamaat war früher ein Feiertag, den jeder für sich beging. Jeder Eredar beschriftete einen Stein mit einer seiner schmerzhaften Erinnerungen. Anschließend dachte man darüber nach, was einen diese Erinnerungen lehren konnten. Dann verpflichtete man sich, mit diesem Wissen die Zukunft zu gestalten.\n\nAm Ende wurden die Steine in der Flamme der Begnadigung aufgelöst, um die Last symbolisch von unseren Seelen zu nehmen.\n\nHeute wird das Tishamaat nicht in Abgeschiedenheit, sondern in der Gemeinschaft gefeiert.\n\nSammelt die Steine von denen ein, die sie Euch anvertrauen, und bringt sie dann zur Flamme.", sourceObjective = "Sammelt 10 Gedächtnissteine, erschafft Euren eigenen Gedächtnisstein und löst die Steine dann in der Flamme der Begnadigung auf.", progress = "Für viele ist dies das erste Tishamaat, an dem sie teilgenommen haben. Für andere eine ferne Erinnerung.", completion = "Die {race} haben zu lange verstreut und vereinsamt gelitten.\n\nHeute erlauben wir es uns, uns aufeinander zu verlassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[78083] = { id = 78083, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unser Pfad voraus", description = "Ah, ich glaube, ich höre den Propheten die Anwesenden vor die Bühne rufen.\n\nIch würde gern wissen, was er und Romuul gleich vor dem versammelten Publikum verkünden wollen.\n\nWir sollten uns beeilen, ja?", sourceObjective = "Sprecht mit Prophet Velen, um die Zeremonie zu beginnen.", completion = "Der heutige Tag markiert den Beginn eines neuen Zeitalters für die Eredar.\n\nWir sind ein Volk, vereint in einem Ziel.\n\nUnd wir werden nie wieder auseinandergerissen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[78097] = { id = 78097, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Funken des Lebens: Der Smaragdgrüne Traum", description = "Folgt der Essenz in den Smaragdgrünen Traum und seht, was Ihr entdecken könnt. Aber nehmt Euch vor den Feinden in Acht, die euren Weg kreuzen könnten.", sourceObjective = "Sammelt bei aktivem Kriegsmodus 100 Funken des Lebens im Smaragdgrünen Traum.", progress = "Wehrt die ruchlosen Gegner ab.", completion = "Gut gemacht!", sourceObjectiveStatus = "unverified-source-field" }
