quests[78113] = { id = 78113, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Herausforderungstour", description = "Hallo noch mal, <Abenteurer/Abenteurerin>!\n\nMöchtet Ihr eine Herausforderung? Das hoffe ich doch, da meine Bronzekollegen neue Herausforderungsstrecken zum Abfliegen für Euch haben.\n\nDoch täuscht Euch nicht, diese sind schwieriger als die vorherigen Strecken. Alle Hindernisse sind noch da, doch entlang des Wegs erwarten Euch keine der Gaben.\n\nSeid Ihr bereit für die Herausforderung?", sourceObjective = "Schließt eine Herausforderungsstrecke in jedem Bereich der Dracheninseln ab.", completion = "Gut gemacht! Ihr meistert wahrlich die Kunst des Drachenreitens.", sourceObjectiveStatus = "unverified-source-field" }
quests[78115] = { id = 78115, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Smaragdspaziergang", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
