quests[78126] = { id = 78126, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pflichten eines Lichtbringers" }
quests[78128] = { id = 78128, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schnell und schneller", description = "Ihr seid daran interessiert, Euch allein zu beweisen, was? Dann habe ich eine Herausforderung für Euch, viel Glück!", sourceObjective = "Schließt ein Blitzschlachtfeld ab.", completion = "Sehr schön, Ihr habt getan, was ich Euch aufgetragen habe.", sourceObjectiveStatus = "unverified-source-field" }
quests[78129] = { id = 78129, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schnell und immer schneller", description = "Ihr habt diese einfache Prüfung überlebt.\n\nIhr müsst aber noch mehr beweisen. Versucht es noch einmal und kehrt zurück, wenn Ihr es geschafft habt.", sourceObjective = "Schließt 3 Blitzschlachtfelder ab.", completion = "Ihr habt bewiesen, dass Ihr ein wenig Ausdauer habt. Ich schätze, das ist annehmbar.", sourceObjectiveStatus = "unverified-source-field" }
quests[78131] = { id = 78131, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Winterhauchgeschenk", sourceObjective = "Auf dem Schildchen am Geschenk steht:\n\nSchöne Feiertage, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[78153] = { id = 78153, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handhabung: Runenprototyp", description = "Ah, ich verstehe! Wir befinden uns in unerforschtem Gebiet, aber ich habe einen Plan.\n\nIhr braucht etwas kosmische Tinte, runenverzierte Krümmrinde und Schattenflammenessenz.\n\nTeilt dieses Rezept mit einem verbündeten Schreiber, dann sollte dieser einen Handwerksauftrag für Euch erfüllen können. Lasst mich meine Notizen mit einem Rezept für eine Rune der Schattenbindung aktualisieren.", sourceObjective = "Fertigt oder erlangt Lydiaras Bindungsrune.", progress = "Ist sie bereit? Wollen wir fortfahren?", completion = "Perfekt!! Natürlich sind wir noch nicht fertig. Wir müssen die Bindung stärken, wenn wir eine Chance haben wollen, dass Fyr'alath unsere Änderungen annimmt.", sourceObjectiveStatus = "unverified-source-field" }
